insert into public.web_recipes (id, title, cuisine, source, url, minutes, servings, technique, prep, precision_level, step_count, score, key_canon, data) values
('www-recipetineats-com-penne-all-arrabbiata-spicy-tomato-pasta', 'Penne all''Arrabbiata (Spicy Tomato Pasta)', 'Italian', 'RecipeTin Eats', 'https://www.recipetineats.com/penne-all-arrabbiata-spicy-tomato-pasta/', 25, 4, 2, 1, 2, 11, 35, array['pasta', 'tomatoes', 'garlic', 'parmesan']::text[], '{"title":"Penne all''Arrabbiata (Spicy Tomato Pasta)","cuisine":"Italian","source":"RecipeTin Eats","url":"https://www.recipetineats.com/penne-all-arrabbiata-spicy-tomato-pasta/","minutes":25,"servings":4,"key":["Pasta","Canned tomatoes","Garlic","Parmesan"],"minor":["Red cayenne chilli","Chilli flakes","Fresh parsley","Olive oil","Salt","Black pepper","Sugar (if needed)"],"amounts":{"Pasta":"400g penne or ziti","Canned tomatoes":"800g crushed","Garlic":"3 cloves, finely minced","Parmesan":"grated, for serving"},"steps":[["On a clean cutting board, finely mince [[3 cloves]] garlic and finely chop [[1]] red cayenne chilli, keeping the seeds in.",null],["Finely grate some Parmesan and finely chop [[2 tsp]] parsley for serving, if using. Set them aside.",null],["Heat [[4 tbsp]] extra virgin olive oil in a large pot over medium heat. Add the garlic and stir for 10 seconds.",null],["Add the chopped chilli and [[0.5 tsp]] chilli flakes to the pot. Cook for 1 minute, or until the garlic is light golden.",1],["Add [[800 g]] crushed tomato, [[1.25 tsp]] salt and [[0.25 tsp]] black pepper to the pot. Rinse out the tomato cans with water and pour that water into the pot too.",null],["Turn the heat up to high and stir. Once it comes to a simmer, turn it back down to medium and simmer for 15 minutes.",15],["Taste the sauce at the 10 minute mark. If it tastes sour, stir in [[0.5 tsp]] white sugar.",null],["Meanwhile, bring a separate large pot of water to the boil with [[1 tbsp]] salt. Add [[400 g]] pasta and cook it per the packet directions.",null],["Just before draining, give the pasta pot a big stir, then scoop out 1 cup of the cooking water and set it aside. Drain the pasta.",null],["Add the pasta into the pot of sauce along with 1/2 cup of the saved pasta water. Toss well, still on the stove, until the pasta is coated with sauce. Add extra pasta water if needed to loosen it.",null],["Divide between bowls and serve immediately with the Parmesan and parsley, if using.",null]],"technique":2,"prep":1,"precision":2,"nutrition":{"calories":567,"protein_g":17,"carbs_g":91,"fat_g":16},"video":null,"country":"IT","effort_steps":5,"ingredients":[{"item":"penne or ziti, or other pasta of choice (short or long)","qty":400,"unit":"g","note":"14 oz","group":"Pasta"},{"item":"cooking/kosher salt","qty":1,"unit":"tbsp","note":"for cooking pasta","group":"Pasta"},{"item":"extra virgin olive oil","qty":4,"unit":"tbsp","group":"Arrabbiata Sauce"},{"item":"garlic","qty":3,"unit":"clove","note":"finely minced","group":"Arrabbiata Sauce"},{"item":"red cayenne pepper chilli","qty":1,"note":"finely chopped (with seeds)","group":"Arrabbiata Sauce"},{"item":"chilli flakes (red pepper flakes)","qty":0.5,"unit":"tsp","group":"Arrabbiata Sauce"},{"item":"canned crushed tomato","qty":800,"unit":"g","note":"28 oz","group":"Arrabbiata Sauce"},{"item":"cooking/kosher salt","qty":1.25,"unit":"tsp","group":"Arrabbiata Sauce"},{"item":"black pepper","qty":0.25,"unit":"tsp","group":"Arrabbiata Sauce"},{"item":"white sugar","qty":0.5,"unit":"tsp","note":"only if needed","group":"Arrabbiata Sauce"},{"item":"Parmesan","note":"finely grated","group":"Serving"},{"item":"parsley","qty":2,"unit":"tsp","note":"finely chopped, optional","group":"Serving"}]}'::jsonb),
('www-budgetbytes-com-bacon-spinach-pasta-parmesan', 'Bacon and Spinach Pasta with Parmesan', 'Italian', 'Budget Bytes', 'https://www.budgetbytes.com/bacon-spinach-pasta-parmesan/', 30, 4, 2, 1, 2, 11, 39, array['pasta', 'spinach', 'bacon', 'parmesan', 'onion', 'broth']::text[], '{"title":"Bacon and Spinach Pasta with Parmesan","cuisine":"Italian","source":"Budget Bytes","url":"https://www.budgetbytes.com/bacon-spinach-pasta-parmesan/","minutes":30,"servings":4,"key":["Pasta","Spinach","Bacon","Parmesan","Onion","Chicken broth"],"minor":[],"amounts":{"Pasta":"½ lb","Spinach":"¼ lb fresh, about 4 cups","Bacon":"6 oz","Parmesan":"⅓ cup grated","Onion":"1 yellow","Chicken broth":"2 cups"},"steps":[["On a clean cutting board, cut [[6 oz]] bacon across the strips into one-inch pieces.",null],["Sauté the bacon in a large skillet until it is brown and crispy. You don''t need any extra fat.",null],["While the bacon cooks, dice [[1]] yellow onion on the cutting board.",null],["Lift the browned bacon out with a slotted spoon into a new bowl. Carefully pour the fat off into a separate bowl, leaving about one tablespoon in the skillet.",null],["Add the diced onion to the same skillet and sauté until soft and transparent. Let the moisture from the onion loosen some of the browned bits on the bottom of the skillet.",null],["Pour [[2 cups]] chicken broth into the skillet and scrape up any remaining browned bits from the bottom.",null],["Add [[0.5 lb]] uncooked pasta to the skillet, put a lid on top, and bring it to a boil over high heat.",null],["Once it boils, give it a quick stir, turn the heat down to low, and simmer for 10 minutes with the lid on. Stir every few minutes to loosen the pasta from the bottom, replacing the lid quickly each time.",10],["After 10 minutes the pasta should be tender and most of the broth absorbed, with a little thick, saucy broth left in the bottom of the skillet.",null],["Add [[0.25 lb]] fresh spinach to the skillet and stir until it has wilted into the pasta.",null],["Turn off the heat. Add the cooked bacon back into the skillet, sprinkle [[0.333 cup]] grated Parmesan over the top, stir to combine, and serve.",null]],"technique":2,"prep":1,"precision":2,"nutrition":{"calories":428,"protein_g":17,"carbs_g":47,"fat_g":19},"video":null,"country":"IT","effort_steps":6,"ingredients":[{"item":"bacon","qty":6,"unit":"oz"},{"item":"yellow onion","qty":1},{"item":"chicken broth","qty":2,"unit":"cup"},{"item":"pasta","qty":0.5,"unit":"lb"},{"item":"fresh spinach","qty":0.25,"unit":"lb","note":"about 4 cups"},{"item":"grated Parmesan","qty":0.333,"unit":"cup"}]}'::jsonb),
('www-recipetineats-com-spicy-chilli-prawn-pasta', 'Spicy Chilli Prawn Pasta (Shrimp)', 'Italian', 'RecipeTin Eats', 'https://www.recipetineats.com/spicy-chilli-prawn-pasta/', 15, 2, 2, 1, 3, 10, 35, array['pasta', 'shrimp', 'tomatoes', 'garlic', 'lemon', 'parmesan']::text[], '{"title":"Spicy Chilli Prawn Pasta (Shrimp)","cuisine":"Italian","source":"RecipeTin Eats","url":"https://www.recipetineats.com/spicy-chilli-prawn-pasta/","minutes":15,"servings":2,"key":["Pasta","Shrimp","Tomato passata","Garlic","Lemon","Parmesan"],"minor":["Anchovies","White wine","Chilli flakes","Fresh parsley","Olive oil"],"amounts":{"Pasta":"180 g fettuccine","Shrimp":"150–180 g medium, peeled","Tomato passata":"1 cup","Garlic":"1 clove, minced","Lemon":"½","Parmesan":"2 tsp finely grated"},"steps":[["Get all the ingredients out and ready to go, because this recipe moves fast! On a clean cutting board, mince [[1 clove]] garlic and finely chop [[0.25 cup]] fresh parsley, plus a little extra for serving.",null],["Bring a large pot of water to the boil. Add a big pinch of salt and [[180 g]] pasta, and cook for the packet time MINUS 1 minute.",null],["Before draining, scoop out a mugful of the pasta cooking water and set it aside. Then drain the pasta (or move it straight from the pot into the sauce if you time it right).",null],["Heat [[1.5 tbsp]] olive oil in a skillet over high heat. Add [[150 g]] prawns and cook for 30 seconds, until the surface just changes from see-through to opaque.",null],["Add [[1 tsp]] chilli flakes and [[2]] anchovies to the skillet and stir briefly. Then add [[0.25 cup]] white wine and the garlic.",null],["Cook for 30 seconds until the wine has mostly evaporated.",null],["Add [[1 cup]] tomato passata, a squeeze of juice from [[0.5]] lemon, [[2 tsp]] parmesan, and some salt and pepper to the skillet.",null],["Bring it to a simmer, then turn the heat down to medium and cook the sauce for 1 minute, stirring often. Don''t cook it longer or the prawns will overcook.",1],["Add the pasta, about 1/2 cup of the saved pasta water and the parsley to the skillet. Toss gently for 1 minute until the sauce thickens again and coats the pasta.",1],["Taste and adjust the salt, pepper and spiciness. Serve immediately with more parsley.",null]],"technique":2,"prep":1,"precision":3,"nutrition":{"calories":544,"protein_g":36,"carbs_g":56,"fat_g":17},"video":null,"country":"IT","effort_steps":5,"ingredients":[{"item":"fettuccine or other pasta of choice","qty":180,"unit":"g","note":"6 oz"},{"item":"olive oil","qty":1.5,"unit":"tbsp"},{"item":"medium prawns/shrimp","qty":150,"qtyMax":180,"unit":"g","note":"peeled and deveined (5-6 oz)"},{"item":"anchovies","qty":2,"note":"whole (or 1/2 tsp anchovy paste)"},{"item":"garlic","qty":1,"unit":"clove","note":"minced"},{"item":"white wine","qty":0.25,"unit":"cup"},{"item":"chilli flakes / red pepper flakes","qty":1,"unit":"tsp","note":"or more"},{"item":"tomato passata","qty":1,"unit":"cup","note":"250 ml"},{"item":"parmesan","qty":2,"unit":"tsp","note":"finely grated"},{"item":"lemon","qty":0.5},{"item":"fresh parsley","qty":0.25,"unit":"cup","note":"finely chopped, plus more to serve"}]}'::jsonb),
('www-melissassouthernstylekitchen-com-easy-shrimp-creole', 'Easy Shrimp Creole', 'Southern', 'Melissa''s Southern Style Kitchen', 'https://www.melissassouthernstylekitchen.com/easy-shrimp-creole/', 40, 6, 4, 3, 2, 12, 59, array['shrimp', 'tomatoes', 'bell peppers', 'onion', 'broth', 'rice', 'butter']::text[], '{"title":"Easy Shrimp Creole","cuisine":"Southern","source":"Melissa''s Southern Style Kitchen","url":"https://www.melissassouthernstylekitchen.com/easy-shrimp-creole/","minutes":40,"servings":6,"key":["Shrimp","Canned tomatoes","Bell pepper","Onion","Chicken broth","Rice","Butter"],"minor":["Celery","Garlic","Creole seasoning","Worcestershire sauce","Tomato paste","Paprika","Cayenne","Bay leaves","Hot sauce","Green onions","Olive oil"],"amounts":{"Shrimp":"2 lbs raw medium-large, peeled","Canned tomatoes":"1 (15 oz) can crushed","Bell pepper":"1 small green","Onion":"1 medium yellow","Chicken broth":"1½ cups chicken stock","Rice":"cooked white rice, for serving","Butter":"2 Tbsp salted"},"steps":[["On a clean cutting board, dice [[1 medium]] yellow onion, [[1 small]] green bell pepper (remove the seeds first) and [[1 rib]] celery.",null],["Mince [[3 cloves]] garlic and thinly slice [[4 medium]] green onions. Keep them separate.",null],["In a large skillet, cook the onion, bell pepper and celery with [[2 tbsp]] salted butter over medium-high heat for 5 minutes, until softened and beginning to brown.",5],["Add the garlic to the skillet and cook for 1 minute longer.",1],["Meanwhile, in a medium mixing bowl, toss [[2 lb]] peeled shrimp with [[2 tsp]] Creole seasoning. Set aside.",null],["To the skillet, add the remaining [[2 tsp]] Creole seasoning, [[1.5 cups]] chicken stock, [[1 can (15 oz)]] crushed tomatoes, [[1 tbsp]] tomato paste and [[1 tbsp]] Worcestershire sauce.",null],["Also add [[1 tsp]] paprika, [[0.5 tsp]] salt, [[0.25 tsp]] cayenne, [[2]] bay leaves and a few dashes of hot sauce to the skillet.",null],["Simmer uncovered on medium-low for 10 minutes to reduce slightly.",10],["Heat a couple of drizzles of olive oil in a separate skillet. Add the seasoned shrimp and cook over medium-high for 1 minute, or until lightly pink.",1],["Move the shrimp into the Creole sauce in the first skillet. Simmer for 3-4 minutes, or until the shrimp is cooked through.",3],["If you want a thicker sauce, stir in more tomato paste [[1 tbsp]] at a time.",null],["Serve immediately with cooked white rice, garnished with the green onion.",null]],"technique":4,"prep":3,"precision":2,"nutrition":{"calories":193,"protein_g":22,"carbs_g":12,"fat_g":6},"video":null,"country":"US","effort_steps":6,"ingredients":[{"item":"yellow onion","qty":1,"unit":"medium","note":"diced"},{"item":"green bell pepper","qty":1,"unit":"small","note":"seeded and diced"},{"item":"celery","qty":1,"unit":"rib","note":"diced"},{"item":"salted butter","qty":2,"unit":"tbsp"},{"item":"garlic","qty":3,"unit":"clove","note":"minced"},{"item":"raw medium-large shrimp (tails on or off)","qty":2,"unit":"lb","note":"peeled and deveined"},{"item":"Creole seasoning","qty":4,"unit":"tsp","note":"divided"},{"item":"chicken stock or shrimp stock","qty":1.5,"unit":"cup"},{"item":"crushed tomatoes","qty":1,"unit":"can (15 oz)"},{"item":"Worcestershire sauce","qty":1,"unit":"tbsp"},{"item":"tomato paste","qty":1,"unit":"tbsp","note":"plus additional as needed"},{"item":"paprika","qty":1,"unit":"tsp"},{"item":"salt","qty":0.5,"unit":"tsp"},{"item":"cayenne","qty":0.25,"unit":"tsp","note":"adjust to taste"},{"item":"dried bay leaves","qty":2},{"item":"hot sauce","note":"a few dashes, adjust to taste"},{"item":"olive oil"},{"item":"cooked white rice","note":"for serving"},{"item":"green onion","qty":4,"unit":"medium","note":"thinly sliced"}]}'::jsonb),
('www-thekitchn-com-smothered-chicken-recipe-23207893', 'Smothered Chicken Recipe (with Creamy Onion Gravy)', 'Southern', 'The Kitchn', 'https://www.thekitchn.com/smothered-chicken-recipe-23207893', 60, 4, 4, 2, 3, 14, 61, array['chicken', 'onion', 'broth', 'flour', 'garlic']::text[], '{"title":"Smothered Chicken Recipe (with Creamy Onion Gravy)","cuisine":"Southern","source":"The Kitchn","url":"https://www.thekitchn.com/smothered-chicken-recipe-23207893","minutes":60,"servings":4,"key":["Chicken legs","Onion","Chicken broth","Flour","Garlic"],"minor":["Smoked paprika","Onion powder","Fresh thyme","Olive oil","Kosher salt","Black pepper"],"amounts":{"Chicken legs":"4 whole (3½ lbs)","Onion":"2 large yellow, thinly sliced","Chicken broth":"2 cups low-sodium","Flour":"½ cup all-purpose","Garlic":"2 cloves, minced"},"steps":[["Place a rack in the middle of the oven and heat the oven to 350°F.",null],["In a shallow dish, stir together [[0.5 cup]] all-purpose flour, [[2 tsp]] smoked paprika, [[1 tsp]] onion powder, [[1 tsp]] kosher salt and [[0.25 tsp]] black pepper.",null],["Pat [[4]] chicken legs dry with paper towels. Dredge them in the flour mixture, turning to coat all sides. Shake off the excess and place them on a plate. Save the leftover flour mixture.",null],["Heat [[2 tbsp]] olive oil in a large ovenproof skillet over medium-high heat until shimmering. Add the chicken and sear until golden-brown, 4 to 5 minutes per side.",4],["While the chicken sears, on a clean cutting board thinly slice [[2 large]] yellow onions (about 3 cups) and finely chop [[2 cloves]] garlic.",null],["When the chicken is ready, move it back to the plate. Add the remaining [[1 tbsp]] olive oil to the same skillet and reduce the heat to medium.",null],["Add the onions to the skillet and season with the remaining [[0.5 tsp]] kosher salt and [[0.25 tsp]] black pepper. Cook, stirring occasionally, until soft and golden-brown, about 8 minutes.",8],["Add the garlic and cook until fragrant, about 1 minute.",1],["Add the leftover flour mixture to the skillet and stir to combine.",null],["Slowly whisk in [[2 cups]] low-sodium chicken broth about 1/4 cup at a time. Bring to a boil, then reduce the heat to keep it at a simmer.",null],["Return the chicken to the skillet skin-side up, nestling each piece into the onion gravy. Pour in any juices left on the plate.",null],["Tuck [[8]] large fresh thyme sprigs between the chicken pieces, nestling them into the gravy.",null],["Move the skillet to the oven. Bake until the chicken is cooked through and reads 165°F in the thickest part on an instant-read thermometer, about 30 minutes.",30],["Throw away the thyme sprigs and serve immediately.",null]],"technique":4,"prep":2,"precision":3,"nutrition":{"calories":948,"protein_g":62,"carbs_g":25,"fat_g":66},"video":null,"country":"US","effort_steps":5,"ingredients":[{"item":"all-purpose flour","qty":0.5,"unit":"cup"},{"item":"smoked paprika","qty":2,"unit":"tsp"},{"item":"onion powder","qty":1,"unit":"tsp"},{"item":"kosher salt","qty":1.5,"unit":"tsp","note":"divided"},{"item":"freshly ground black pepper","qty":0.5,"unit":"tsp","note":"divided"},{"item":"whole chicken legs","qty":4,"note":"about 3 1/2 pounds total"},{"item":"olive oil","qty":3,"unit":"tbsp","note":"divided"},{"item":"yellow onions","qty":2,"unit":"large"},{"item":"garlic","qty":2,"unit":"clove"},{"item":"low-sodium chicken broth","qty":2,"unit":"cup"},{"item":"fresh thyme","qty":8,"unit":"large sprig"}]}'::jsonb),
('www-budgetbytes-com-arroz-con-pollo', 'Arroz Con Pollo (Puerto Rican Chicken and Rice)', 'Caribbean', 'Budget Bytes', 'https://www.budgetbytes.com/arroz-con-pollo/', 50, 5, 3, 3, 3, 13, 58, array['chicken', 'rice', 'broth', 'bell peppers', 'onion', 'peas', 'garlic']::text[], '{"title":"Arroz Con Pollo (Puerto Rican Chicken and Rice)","cuisine":"Caribbean","source":"Budget Bytes","url":"https://www.budgetbytes.com/arroz-con-pollo/","minutes":50,"servings":5,"key":["Chicken thighs","Rice","Chicken broth","Bell pepper","Onion","Frozen peas","Garlic"],"minor":["Adobo seasoning","Sofrito","Tomato sauce","Pimiento-stuffed olives","Sazón seasoning","Cilantro","Cooking oil","Salt"],"amounts":{"Chicken thighs":"1.5 lbs boneless","Rice":"2 cups","Chicken broth":"2½ cups chicken stock","Bell pepper":"1 red, small dice, divided","Onion":"½ yellow, small dice","Frozen peas":"½ cup","Garlic":"3 cloves, minced"},"steps":[["On a clean cutting board, small-dice [[1]] red bell pepper and [[0.5]] yellow onion, and mince [[3 cloves]] garlic. Keep the bell pepper in its own pile because you''ll use it in two parts.",null],["Place [[1.5 lb]] chicken thighs in a shallow bowl and rub them with [[2 tsp]] cooking oil and [[2 tsp]] adobo seasoning.",null],["Refrigerate the chicken uncovered for thirty minutes.",30],["Heat a Dutch oven over medium-high heat and add the remaining [[2 tbsp]] cooking oil. Once it''s shimmering, add the chicken thighs in an even layer.",null],["Sear each side until golden brown, about 3 minutes per side. Remove the chicken and set it aside.",3],["Add [[0.25 cup]] sofrito, the diced onion and half of the diced red pepper to the chicken fat in the Dutch oven. Sauté until the onion is translucent, about 3 minutes.",3],["Add the garlic, [[2 tbsp]] tomato sauce and [[0.5 cup]] olives. Sauté until fragrant and most of the liquid has cooked out.",null],["Add [[2 cups]] rice, [[1.5 tsp]] sazón and [[0.25 tsp]] salt to the Dutch oven. Gently mix until every grain is coated.",null],["Add [[2.5 cups]] chicken stock and bring to a boil. Let it boil without stirring until the stock partly evaporates and you can see rice on the surface with little steam vents, about 5 to 8 minutes.",5],["Place the reserved chicken thighs on top of the rice. Lower the heat to low and cover with a tight-fitting lid.",null],["Cook for 20 minutes, until the stock has evaporated and the rice is cooked through.",20],["Remove the chicken and set it aside. Stir [[0.5 cup]] frozen peas into the rice and fluff it.",null],["Return the chicken to the pot. Garnish with the rest of the diced red pepper and [[0.25 cup]] cilantro, if using.",null]],"technique":3,"prep":3,"precision":3,"nutrition":{"calories":591,"protein_g":36,"carbs_g":70,"fat_g":17},"video":null,"country":"US","effort_steps":6,"ingredients":[{"item":"adobo seasoning","qty":2,"unit":"tsp"},{"item":"boneless chicken thighs","qty":1.5,"unit":"lb"},{"item":"cooking oil","qty":2.667,"unit":"tbsp","note":"divided"},{"item":"sofrito","qty":0.25,"unit":"cup"},{"item":"red bell pepper","qty":1,"note":"small dice, divided"},{"item":"yellow onion","qty":0.5,"note":"small dice"},{"item":"garlic","qty":3,"unit":"clove","note":"minced"},{"item":"tomato sauce","qty":2,"unit":"tbsp"},{"item":"pimiento stuffed Spanish olives","qty":0.5,"unit":"cup"},{"item":"rice","qty":2,"unit":"cup"},{"item":"chicken stock","qty":2.5,"unit":"cup"},{"item":"salt","qty":0.25,"unit":"tsp"},{"item":"sazón seasoning","qty":1.5,"unit":"tsp"},{"item":"frozen green peas","qty":0.5,"unit":"cup"},{"item":"cilantro","qty":0.25,"unit":"cup","note":"optional garnish"}]}'::jsonb),
('www-thekitchn-com-jamaican-chicken-curry-recipe-23580119', 'Jamaican Curry Chicken', 'Caribbean', 'The Kitchn', 'https://www.thekitchn.com/jamaican-chicken-curry-recipe-23580119', 60, 6, 4, 3, 2, 15, 62, array['chicken', 'potatoes', 'carrots', 'onion', 'garlic', 'scallions']::text[], '{"title":"Jamaican Curry Chicken","cuisine":"Caribbean","source":"The Kitchn","url":"https://www.thekitchn.com/jamaican-chicken-curry-recipe-23580119","minutes":60,"servings":6,"key":["Chicken pieces","Potatoes","Carrots","Onion","Garlic","Scallions"],"minor":["Jamaican curry powder","Fresh thyme","Scotch bonnet or habanero","Maggi all-purpose seasoning","Garlic powder","Onion powder","White pepper","Black pepper","Chicken bouillon cube","Allspice berries","Vegetable oil","Kosher salt"],"amounts":{"Chicken pieces":"4 lbs bone-in, cut into 3-inch pieces","Potatoes":"2 medium white, diced","Carrots":"1 medium, diced","Onion":"1 small red, chopped","Garlic":"2 cloves, minced","Scallions":"3 medium, sliced"},"steps":[["On a clean cutting board, coarsely chop [[1 small]] red onion, thinly slice [[3 medium]] scallions, and trim and thinly slice [[1 small]] habanero or scotch bonnet pepper.",null],["Pick [[1 tbsp]] fresh thyme leaves off their sprigs and mince [[2 cloves]] garlic. Keep the garlic separate for later.",null],["Cut [[4 lb]] bone-in chicken into rough 3-inch pieces, halving thighs or drumsticks across the bone.",null],["In a large bowl, combine the thyme, red onion, scallions, hot pepper, [[2 tbsp]] Maggi seasoning, [[2 tbsp]] curry powder, [[1 tsp]] garlic powder, [[1 tsp]] onion powder, [[0.5 tsp]] white pepper and [[0.5 tsp]] black pepper.",null],["Add the chicken pieces to the same bowl and toss to coat, massaging the seasonings in with your hands (wear gloves if you like).",null],["Cover and refrigerate for at least 1 hour or overnight.",60],["Meanwhile, peel and dice [[2 medium]] white potatoes and [[1 medium]] carrot on the cutting board.",null],["Heat [[2 tbsp]] vegetable oil in a large pot over medium heat until shimmering. Add the garlic and the remaining [[1 tsp]] curry powder and stir constantly until fragrant, about 15 seconds.",null],["Move the chicken into the pot, leaving the marinade behind in the bowl. Cover and cook for 5 minutes, lowering the heat if needed.",5],["Uncover and stir, making sure the chicken isn''t sticking.",null],["Mix the leftover marinade with [[2 cups]] water and pour it into the pot.",null],["Cover and boil, stirring occasionally, until the chicken is cooked through and tender, 30 to 35 minutes. Keep the liquid about halfway up the chicken, adding water as needed.",30],["Add the potatoes, carrot, [[1]] bouillon cube and [[6]] allspice berries to the pot. Stir until the bouillon dissolves.",null],["Taste and season with kosher salt.",null],["Cover and boil until the potatoes are fork tender and the sauce thickens to a gravy, 8 to 10 minutes. Serve with roti or rice.",8]],"technique":4,"prep":3,"precision":2,"nutrition":{"calories":819,"protein_g":60,"carbs_g":27,"fat_g":51},"video":null,"country":"JM","effort_steps":5,"ingredients":[{"item":"fresh thyme leaves","qty":1,"unit":"tbsp","note":"from about 15 sprigs"},{"item":"red onion","qty":1,"unit":"small","note":"coarsely chopped"},{"item":"scallions","qty":3,"unit":"medium","note":"thinly sliced (about 1/3 cup)"},{"item":"habanero or scotch bonnet pepper","qty":1,"unit":"small","note":"trimmed and thinly sliced"},{"item":"Maggi all-purpose seasoning","qty":2,"unit":"tbsp"},{"item":"Jamaican curry powder","qty":2.333,"unit":"tbsp","note":"2 tablespoons plus 1 teaspoon, divided"},{"item":"garlic powder","qty":1,"unit":"tsp"},{"item":"onion powder","qty":1,"unit":"tsp"},{"item":"ground white pepper","qty":0.5,"unit":"tsp"},{"item":"freshly ground black pepper","qty":0.5,"unit":"tsp"},{"item":"bone-in chicken pieces","qty":4,"unit":"lb","note":"cut into rough 3-inch pieces (halve thighs or drumsticks across the bone)"},{"item":"garlic","qty":2,"unit":"clove","note":"minced"},{"item":"vegetable oil","qty":2,"unit":"tbsp"},{"item":"water","qty":2,"unit":"cup"},{"item":"white potatoes","qty":2,"unit":"medium","note":"about 12 ounces total, peeled and diced"},{"item":"carrot","qty":1,"unit":"medium","note":"peeled and diced"},{"item":"chicken bouillon cube","qty":1,"note":"or 1 teaspoon chicken bouillon powder or paste"},{"item":"allspice berries","qty":6},{"item":"kosher salt"},{"item":"roti or steamed rice","note":"for serving"}]}'::jsonb),
('www-thekitchn-com-cheese-on-toast-recipe-23309869', 'Cheese on Toast (Open-Faced Grilled Cheese)', 'British', 'The Kitchn', 'https://www.thekitchn.com/cheese-on-toast-recipe-23309869', 15, 2, 1, 1, 2, 10, 27, array['bread', 'cheddar']::text[], '{"title":"Cheese on Toast (Open-Faced Grilled Cheese)","cuisine":"British","source":"The Kitchn","url":"https://www.thekitchn.com/cheese-on-toast-recipe-23309869","minutes":15,"servings":2,"key":["Bread","Cheddar"],"minor":["Worcestershire sauce"],"amounts":{"Bread":"2 slices soft white sandwich bread","Cheddar":"4 oz sharp, shredded (about 1 cup)"},"steps":[["Place an oven rack 4 to 6 inches below the broiler, then set the oven to broil on high heat.",null],["Line a rimmed baking sheet with aluminum foil and fit a wire rack inside it.",null],["Grate [[4 oz]] sharp cheddar cheese on the large holes of a box grater (about 1 cup).",null],["Place [[2 slices]] white sandwich bread on the rack. Broil until deep golden brown, about 2 minutes.",2],["Flip the bread and broil until the second side is deep golden brown, about 2 minutes more.",2],["Take the baking sheet out of the oven. Lean the toasts against each other so they stand upright on the rack for 2 minutes, so they cool slightly and crisp on both sides.",2],["Lay the toasts flat on the rack. Divide the cheese between them, making sure the edges are completely covered so the crusts don''t burn. It will look piled high, but it melts down.",null],["Drizzle [[2 tsp]] Worcestershire sauce onto each toast.",null],["Broil until the cheese is bubbly and deep golden-brown in spots, 2 to 4 minutes.",2],["Add an extra dash of Worcestershire sauce if you like. Let cool for 1 to 2 minutes before serving.",1]],"technique":1,"prep":1,"precision":2,"nutrition":{"calories":316,"protein_g":17,"carbs_g":17,"fat_g":20},"video":null,"country":"GB","effort_steps":5,"ingredients":[{"item":"sharp cheddar cheese","qty":4,"unit":"oz","note":"shredded (about 1 cup)"},{"item":"soft white sandwich bread","qty":2,"unit":"slice"},{"item":"homemade or Lea and Perrins Worcestershire sauce","qty":4,"unit":"tsp","note":"divided, plus more if desired"}]}'::jsonb),
('www-recipetineats-com-bangers-and-mash-sausage-with-onion-gravy', 'Bangers and Mash (Sausage with Onion Gravy)', 'British', 'RecipeTin Eats', 'https://www.recipetineats.com/bangers-and-mash-sausage-with-onion-gravy/', 25, 4, 4, 1, 2, 11, 49, array['sausage', 'onion', 'broth', 'flour', 'butter', 'potatoes', 'peas']::text[], '{"title":"Bangers and Mash (Sausage with Onion Gravy)","cuisine":"British","source":"RecipeTin Eats","url":"https://www.recipetineats.com/bangers-and-mash-sausage-with-onion-gravy/","minutes":25,"servings":4,"key":["Sausages","Onion","Beef broth","Flour","Butter","Potatoes","Frozen peas"],"minor":["Garlic","Dark soy sauce","Oil","Salt","Black pepper"],"amounts":{"Sausages":"8","Onion":"1 large, finely sliced","Beef broth":"2 cups","Flour":"3 tbsp","Butter":"25g (1½ tbsp), if needed","Potatoes":"mashed potato, to serve","Frozen peas":"peas, to serve"},"steps":[["On a clean cutting board, halve and finely slice [[1 large]] onion, and mince [[2 cloves]] garlic.",null],["Heat [[0.5 tbsp]] oil in a large skillet over medium-high heat. Add [[8]] sausages and cook, turning, until browned and cooked through, about 8 minutes depending on size.",8],["Move the sausages onto a plate and turn the heat down to medium.",null],["Check the oil in the skillet: you need around 2 tbsp left. If there''s much less, add [[25 g]] butter.",null],["Add the onion and garlic to the skillet and cook until golden brown, around 4 minutes.",4],["Add [[3 tbsp]] flour and mix it through. Cook, stirring constantly, for 1 minute.",1],["Add about 3/4 cup of the [[2 cups]] beef broth and mix it into the onion to form a sludge. Then add the rest of the broth and mix until combined, using a whisk if it''s lumpy.",null],["Add [[0.25 tsp]] dark soy sauce, if using.",null],["Simmer, stirring, for 2 to 3 minutes until the gravy thickens but is slightly thinner than you want, because it thickens more as you serve.",2],["Add [[0.25 tsp]] salt and [[0.5 tsp]] black pepper. Stir, taste, and add more salt if needed.",null],["Serve the sausages with plenty of gravy, with mashed potato and peas on the side.",null]],"technique":4,"prep":1,"precision":2,"nutrition":{"calories":666,"protein_g":36,"carbs_g":8,"fat_g":53},"video":null,"country":"GB","effort_steps":6,"ingredients":[{"item":"oil","qty":0.5,"unit":"tbsp"},{"item":"sausages of choice","qty":8},{"item":"unsalted butter","qty":25,"unit":"g","note":"1 1/2 tbsp, if needed"},{"item":"onion (yellow, white or brown)","qty":1,"unit":"large","note":"halved and finely sliced"},{"item":"garlic","qty":2,"unit":"clove","note":"minced"},{"item":"flour (plain)","qty":3,"unit":"tbsp"},{"item":"beef stock/broth, low sodium","qty":2,"unit":"cup","note":"store bought or homemade"},{"item":"dark soy sauce (or gravy browner)","qty":0.25,"unit":"tsp"},{"item":"cooking salt / kosher salt","qty":0.25,"unit":"tsp"},{"item":"black pepper","qty":0.5,"unit":"tsp"},{"item":"mashed potato","group":"To Serve"},{"item":"peas","group":"To Serve"}]}'::jsonb),
('www-themediterraneandish-com-gambas-al-ajillo-spanish-shrimp', 'Gambas al Ajillo (Spanish Garlic Shrimp)', 'Spanish', 'The Mediterranean Dish', 'https://www.themediterraneandish.com/gambas-al-ajillo-spanish-shrimp/', 10, 4, 2, 2, 2, 8, 35, array['shrimp', 'garlic', 'lemon', 'bread']::text[], '{"title":"Gambas al Ajillo (Spanish Garlic Shrimp)","cuisine":"Spanish","source":"The Mediterranean Dish","url":"https://www.themediterraneandish.com/gambas-al-ajillo-spanish-shrimp/","minutes":10,"servings":4,"key":["Shrimp","Garlic","Lemon","Bread"],"minor":["Extra virgin olive oil","Red pepper flakes","Sweet Spanish paprika","Dry sherry or dry white wine","Fresh parsley","Kosher salt"],"amounts":{"Shrimp":"1 lb large, peeled and deveined","Garlic":"10 cloves, chopped","Lemon":"½, juiced","Bread":"crusty bread, for serving"},"steps":[["On a clean cutting board, chop [[10 cloves]] garlic and [[0.5 cup]] fresh parsley. Squeeze the juice from [[0.5]] lemon into a small bowl.",null],["Pat [[1 lb]] shrimp dry with paper towels and season with kosher salt. Set aside while you start the sauce.",null],["Heat [[0.5 cup]] extra virgin olive oil in a pan over medium heat until shimmering but not smoking.",null],["Add the garlic and [[1 tsp]] red pepper flakes to the pan. Cook, stirring, for 30 to 60 seconds, until the garlic takes on a little color. Don''t let it brown or burn.",null],["Add the shrimp and [[1 tsp]] paprika to the pan. Cook, tossing regularly, until the shrimp turn opaque and pearly pink, about 3 minutes depending on their size.",3],["Take the pan off the heat as soon as the shrimp are cooked.",null],["With the pan still off the heat, stir in [[2 tbsp]] sherry or white wine, the lemon juice and the parsley.",null],["Move the shrimp and all the sauce into a serving bowl. Serve with your favorite crusty bread for dipping.",null]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":250,"protein_g":16,"carbs_g":2,"fat_g":19},"video":null,"country":"ES","effort_steps":5,"ingredients":[{"item":"large shrimp","qty":1,"unit":"lb","note":"peeled and deveined"},{"item":"kosher salt"},{"item":"extra virgin olive oil","qty":0.5,"unit":"cup"},{"item":"garlic","qty":10,"unit":"clove","note":"chopped"},{"item":"red pepper flakes","qty":1,"unit":"tsp","note":"or less for a milder sauce"},{"item":"paprika","qty":1,"unit":"tsp"},{"item":"dry sherry or dry white wine","qty":2,"unit":"tbsp"},{"item":"lemon","qty":0.5,"note":"juiced"},{"item":"fresh parsley","qty":0.5,"unit":"cup","note":"chopped"}]}'::jsonb),
('thewoksoflife-com-egg-fried-rice', 'Egg Fried Rice', 'Chinese', 'The Woks of Life', 'https://thewoksoflife.com/egg-fried-rice/', 25, 6, 2, 2, 2, 11, 43, array['rice', 'eggs', 'onion', 'bell peppers', 'peas', 'scallions']::text[], '{"title":"Egg Fried Rice","cuisine":"Chinese","source":"The Woks of Life","url":"https://thewoksoflife.com/egg-fried-rice/","minutes":25,"servings":6,"key":["Rice","Eggs","Onion","Bell peppers","Frozen peas","Scallions"],"minor":["Paprika","Turmeric","Black pepper"],"amounts":{"Rice":"5 cups cooked","Eggs":"5 large","Onion":"1 medium","Bell peppers":"1/2 red bell pepper","Frozen peas":"1/2 cup, thawed","Scallions":"2"},"steps":[["On a clean cutting board, finely chop [[1 medium]] onion and [[0.5]] red bell pepper, and chop [[2]] scallions. Make sure [[0.5 cup]] frozen peas are thawed.",null],["Put [[5 cups]] cooked rice in a large bowl and fluff it with a fork, breaking apart all the clumps. If your rice is freshly cooked, let it cool uncovered first.",null],["In a new bowl, beat [[3]] of the eggs.",null],["In a second new bowl, beat the remaining [[2]] eggs with [[2 tbsp]] water, [[0.25 tsp]] paprika and [[0.25 tsp]] turmeric. This is your spiced egg.",null],["Heat a wok over medium-high heat and add [[2 tbsp]] oil. Pour in the 3 plain eggs and scramble them, then take them out and set them aside on a plate.",null],["Turn the same wok up to high heat and add the remaining [[1 tbsp]] oil. Add the onion and bell pepper and stir-fry for 1-2 minutes.",1],["Add the rice to the wok and stir-fry for 2 minutes, using a scooping motion to break up any clumps.",2],["Pour the spiced egg mixture over the rice and stir-fry for about 1 minute, until the rice is coated.",1],["Add the peas and stir continuously for 1 minute.",1],["Sprinkle [[1.5 tsp]] salt, [[0.25 tsp]] sugar and [[0.25 tsp]] black pepper over the rice and mix well.",null],["If the rice seems dry, add a splash of water or stock. Fold in the scrambled eggs and the scallions, then serve.",null]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":308,"protein_g":9,"carbs_g":42,"fat_g":11},"video":null,"country":"CN","effort_steps":8,"ingredients":[{"item":"cooked rice","qty":5,"unit":"cup"},{"item":"eggs","qty":5,"unit":"large","note":"divided"},{"item":"paprika","qty":0.25,"unit":"tsp"},{"item":"turmeric","qty":0.25,"unit":"tsp"},{"item":"oil","qty":3,"unit":"tbsp","note":"divided"},{"item":"onion","qty":1,"unit":"medium","note":"finely chopped"},{"item":"red bell pepper","qty":0.5,"note":"finely chopped"},{"item":"frozen peas","qty":0.5,"unit":"cup","note":"thawed"},{"item":"salt","qty":1.5,"unit":"tsp"},{"item":"sugar","qty":0.25,"unit":"tsp"},{"item":"black pepper","qty":0.25,"unit":"tsp"},{"item":"scallions","qty":2,"note":"chopped"}]}'::jsonb),
('thewoksoflife-com-chicken-lo-mein', 'Restaurant-Style Chicken Lo Mein', 'Chinese', 'The Woks of Life', 'https://thewoksoflife.com/chicken-lo-mein/', 30, 6, 2, 3, 2, 12, 47, array['noodles', 'chicken', 'cabbage', 'carrots', 'bean sprout', 'scallions', 'soy sauce']::text[], '{"title":"Restaurant-Style Chicken Lo Mein","cuisine":"Chinese","source":"The Woks of Life","url":"https://thewoksoflife.com/chicken-lo-mein/","minutes":30,"servings":6,"key":["Noodles","Chicken thighs","Cabbage","Carrots","Bean sprouts","Scallions","Soy sauce"],"minor":["Dark soy sauce","Oyster sauce","Sesame oil","Shaoxing wine","Garlic","Cornstarch","White pepper"],"amounts":{"Noodles":"1 lb fresh lo mein egg noodles","Chicken thighs":"8 oz, thinly sliced","Cabbage":"4 cups shredded","Carrots":"2 medium, julienned","Bean sprouts":"2 cups","Scallions":"2, julienned","Soy sauce":"1 tbsp light + 4 tsp dark"},"steps":[["On a clean cutting board, cut [[8 oz]] chicken thighs into thin strips. Mince [[1 clove]] garlic, shred [[4 cups]] cabbage, julienne [[2 medium]] carrots and julienne [[2]] scallions.",null],["Check your [[1 lb]] lo mein noodles: if they are raw, boil them before stir-frying. If they are pre-cooked, just let them come to room temperature.",null],["In a medium bowl, combine the chicken with [[2 tsp]] cornstarch, [[2 tsp]] water, [[2 tsp]] oil and [[1 tsp]] oyster sauce.",null],["In a new bowl, stir [[2 tbsp]] hot water with [[0.125 tsp]] salt and [[0.125 tsp]] sugar until dissolved.",null],["Into that same bowl, add [[1 tbsp]] light soy sauce, [[4 tsp]] dark soy sauce, [[1 tsp]] sesame oil and [[0.125 tsp]] white pepper. This is your sauce.",null],["Heat a wok over high heat and add 2 tablespoons oil. Sear the chicken for a couple of minutes until browned, then remove it and set it aside.",2],["Add another couple of tablespoons of oil to the wok, then add the garlic. After 10 seconds, add the cabbage and carrots.",null],["Stir-fry on high heat for a minute, then pour [[1 tbsp]] Shaoxing wine in a circle around the edge of the wok.",1],["Put the noodles and the chicken into the wok. Pour the sauce on top and mix well from the bottom up for about 30 seconds.",null],["Turn the heat down to medium and cover the wok for one minute.",1],["Uncover and stir-fry the noodles. If they look dry, add 1/4 cup water or stock. Keep stir-frying until the noodles are loose and heated through.",null],["Add [[2 cups]] bean sprouts and the scallions, stir-fry for one more minute, and serve.",1]],"technique":2,"prep":3,"precision":2,"nutrition":{"calories":306,"protein_g":13,"carbs_g":42,"fat_g":5},"video":null,"country":"CN","effort_steps":7,"ingredients":[{"item":"fresh lo mein egg noodles","qty":1,"unit":"lb"},{"item":"boneless skinless chicken thighs","qty":8,"unit":"oz","note":"or chicken breast, cut into thin strips"},{"item":"cornstarch","qty":2,"unit":"tsp"},{"item":"water","qty":2,"unit":"tsp"},{"item":"oil","qty":2,"unit":"tsp","note":"plus more for cooking"},{"item":"oyster sauce","qty":1,"unit":"tsp"},{"item":"hot water","qty":2,"unit":"tbsp"},{"item":"salt","qty":0.125,"unit":"tsp"},{"item":"sugar","qty":0.125,"unit":"tsp"},{"item":"light soy sauce","qty":1,"unit":"tbsp"},{"item":"dark soy sauce","qty":4,"unit":"tsp"},{"item":"sesame oil","qty":1,"unit":"tsp"},{"item":"white pepper","qty":0.125,"unit":"tsp"},{"item":"garlic","qty":1,"unit":"clove","note":"minced"},{"item":"cabbage","qty":4,"unit":"cup","note":"shredded"},{"item":"carrots","qty":2,"unit":"medium","note":"julienned, about 1 1/2 cups"},{"item":"Shaoxing wine","qty":1,"unit":"tbsp","note":"or dry sherry cooking wine"},{"item":"mung bean sprouts","qty":2,"unit":"cup"},{"item":"scallions","qty":2,"note":"julienned"}]}'::jsonb),
('thewoksoflife-com-cashew-chicken', 'Cashew Chicken', 'Chinese', 'The Woks of Life', 'https://thewoksoflife.com/cashew-chicken/', 30, 6, 4, 3, 3, 12, 59, array['chicken', 'cashew', 'bell peppers', 'scallions', 'broth', 'soy sauce']::text[], '{"title":"Cashew Chicken","cuisine":"Chinese","source":"The Woks of Life","url":"https://thewoksoflife.com/cashew-chicken/","minutes":30,"servings":6,"key":["Chicken breast","Cashews","Bell peppers","Scallions","Broth","Soy sauce"],"minor":["Ginger","Garlic","Water chestnuts","Oyster sauce","Hoisin sauce","Honey","Shaoxing wine","Rice vinegar","Sesame oil","Cornstarch","White pepper"],"amounts":{"Chicken breast":"1 lb, 1-inch pieces","Cashews":"1 cup unsalted roasted","Bell peppers":"1/2 cup chopped red","Scallions":"1/2 cup chopped","Broth":"1/2 cup low-sodium chicken stock","Soy sauce":"2 tbsp light + 1 tsp dark"},"steps":[["Roast [[1 cup]] unsalted cashews in the oven at 350°F (180°C) for 5 minutes, then set them aside.",5],["On a clean cutting board, cut [[1 lb]] chicken breast into 1-inch (2.5cm) pieces. Grate [[1 tsp]] ginger, mince [[2 cloves]] garlic, chop [[0.5 cup]] red bell pepper and [[0.5 cup]] scallions, and cut [[0.5 cup]] water chestnuts into 1/2-inch (1cm) pieces.",null],["In a new bowl, mix the chicken with [[1 tbsp]] cornstarch, [[3 tbsp]] water, [[1 tsp]] neutral oil and [[2 tsp]] oyster sauce until the liquid is absorbed.",null],["In a separate new bowl, mix the sauce: [[0.5 cup]] low sodium chicken stock, [[1.5 tbsp]] honey, [[2 tbsp]] light soy sauce, [[1 tsp]] hoisin sauce, [[1 tsp]] dark soy sauce, [[0.5 tsp]] rice wine vinegar, [[0.5 tsp]] sesame oil and [[0.125 tsp]] ground white pepper.",null],["In a small cup, mix [[2 tbsp]] cornstarch with [[2 tbsp]] water to make a slurry.",null],["Heat a wok over high heat until it is smoking. Spread [[2 tbsp]] neutral oil around the edge of the wok.",null],["Add the marinated chicken and spread it out evenly. Fry 1 minute on each side, then move it to a bowl. It should be browned outside and about 80% cooked.",2],["Add the remaining [[1 tbsp]] oil and the ginger to the wok and fry for 5 seconds. Add the garlic, then right away add the bell pepper, scallions and water chestnuts. Stir-fry for 30 seconds.",null],["Spread [[1.5 tbsp]] Shaoxing wine around the edge of the wok and stir-fry for 10 seconds.",null],["Pour the sauce into the wok, letting it wash over the sides. Add the chicken and its juices back in. Once it is simmering, add the roasted cashews.",null],["Stir the cornstarch slurry and add about 3/4 of it, adding more or less for the thickness you like. Simmer and stir until the sauce thickens and coats everything evenly.",null],["Plate and serve right away with steamed rice.",null]],"technique":4,"prep":3,"precision":3,"nutrition":{"calories":340,"protein_g":22,"carbs_g":20,"fat_g":20},"video":null,"country":"CN","effort_steps":6,"ingredients":[{"item":"boneless skinless chicken breast","qty":1,"unit":"lb","note":"cut into 1-inch (2.5cm) pieces","group":"Chicken and marinade"},{"item":"cornstarch","qty":1,"unit":"tbsp","group":"Chicken and marinade"},{"item":"water","qty":3,"unit":"tbsp","group":"Chicken and marinade"},{"item":"neutral oil","qty":1,"unit":"tsp","group":"Chicken and marinade"},{"item":"oyster sauce","qty":2,"unit":"tsp","group":"Chicken and marinade"},{"item":"low sodium chicken stock","qty":0.5,"unit":"cup","group":"Sauce"},{"item":"honey","qty":1.5,"unit":"tbsp","group":"Sauce"},{"item":"light soy sauce","qty":2,"unit":"tbsp","group":"Sauce"},{"item":"hoisin sauce","qty":1,"unit":"tsp","group":"Sauce"},{"item":"dark soy sauce","qty":1,"unit":"tsp","group":"Sauce"},{"item":"rice wine vinegar","qty":0.5,"unit":"tsp","group":"Sauce"},{"item":"sesame oil","qty":0.5,"unit":"tsp","group":"Sauce"},{"item":"ground white pepper","qty":0.125,"unit":"tsp","group":"Sauce"},{"item":"neutral oil","qty":3,"unit":"tbsp","note":"divided","group":"Rest of the dish"},{"item":"ginger","qty":1,"unit":"tsp","note":"grated","group":"Rest of the dish"},{"item":"garlic","qty":2,"unit":"clove","note":"minced","group":"Rest of the dish"},{"item":"red bell pepper","qty":0.5,"unit":"cup","note":"chopped","group":"Rest of the dish"},{"item":"scallions","qty":0.5,"unit":"cup","note":"chopped","group":"Rest of the dish"},{"item":"water chestnuts","qty":0.5,"unit":"cup","note":"cut into 1/2-inch (1cm) pieces","group":"Rest of the dish"},{"item":"Shaoxing wine","qty":1.5,"unit":"tbsp","group":"Rest of the dish"},{"item":"unsalted cashews","qty":1,"unit":"cup","note":"roasted at 350°F (180°C) for 5 mins","group":"Rest of the dish"},{"item":"cornstarch","qty":2,"unit":"tbsp","note":"mixed with 2 tablespoons (30ml) water","group":"Rest of the dish"}]}'::jsonb),
('thewoksoflife-com-stir-fried-shrimp-eggs', 'Stir-fried Shrimp and Eggs', 'Chinese', 'The Woks of Life', 'https://thewoksoflife.com/stir-fried-shrimp-eggs/', 15, 4, 2, 1, 2, 8, 33, array['shrimp', 'eggs', 'scallions']::text[], '{"title":"Stir-fried Shrimp and Eggs","cuisine":"Chinese","source":"The Woks of Life","url":"https://thewoksoflife.com/stir-fried-shrimp-eggs/","minutes":15,"servings":4,"key":["Frozen shrimp","Eggs","Scallions"],"minor":["Sesame oil","White pepper","Chinese toon sprouts (optional)"],"amounts":{"Frozen shrimp":"12 oz, peeled and deveined","Eggs":"8 large","Scallions":"2, chopped"},"steps":[["Take [[8 large]] eggs out of the fridge early so they come to room temperature, and clean [[12 oz]] shrimp (peeled and deveined).",null],["On a clean cutting board, chop [[2]] scallions. If using [[0.25 cup]] toon sprouts, wash them. Set a little scallion and toon sprouts aside for garnish.",null],["In a large bowl, beat the eggs with [[0.5 tsp]] salt, [[0.125 tsp]] white pepper and [[1 tsp]] sesame oil. Stir in the rest of the scallions and sprouts.",null],["Bring about 3 cups of water to a boil in a pot and toss in the shrimp just until they turn pink. This is very fast.",null],["Drain the shrimp, give them a quick rinse, and add the warm shrimp into the bowl with the egg mixture.",null],["Heat a wok on high until nearly smoking, add [[0.25 cup]] canola oil and swirl it all around the wok.",null],["Pour in the egg mixture. With a wooden spoon or spatula, fold the eggs gently but quickly, like making scrambled eggs.",null],["Once the eggs look done (be careful not to overcook them), move them to a plate, garnish with the saved scallion and sprouts, and serve with steamed rice.",null]],"technique":2,"prep":1,"precision":2,"nutrition":{"calories":346,"protein_g":29,"carbs_g":1,"fat_g":25},"video":null,"country":"CN","effort_steps":5,"ingredients":[{"item":"shrimp","qty":12,"unit":"oz","note":"340g, peeled and deveined"},{"item":"eggs","qty":8,"unit":"large","note":"at room temperature; very important"},{"item":"salt","qty":0.5,"unit":"tsp","note":"or to taste"},{"item":"ground white pepper","qty":0.125,"unit":"tsp","note":"or to taste"},{"item":"sesame oil","qty":1,"unit":"tsp"},{"item":"scallions","qty":2,"note":"chopped"},{"item":"Chinese toon sprouts","qty":0.25,"unit":"cup","note":"xiang chun miao, totally optional"},{"item":"canola oil","qty":0.25,"unit":"cup"}]}'::jsonb),
('www-justonecookbook-com-chicken-teriyaki', 'Chicken Teriyaki', 'Japanese', 'Just One Cookbook', 'https://www.justonecookbook.com/chicken-teriyaki/', 20, 2, 3, 1, 2, 13, 42, array['chicken', 'soy sauce', 'mirin', 'sake']::text[], '{"title":"Chicken Teriyaki","cuisine":"Japanese","source":"Just One Cookbook","url":"https://www.justonecookbook.com/chicken-teriyaki/","minutes":20,"servings":2,"key":["Chicken thighs","Soy sauce","Mirin","Sake"],"minor":["Black pepper"],"amounts":{"Chicken thighs":"3/4-1 lb boneless, skinless","Soy sauce":"2 tbsp","Mirin":"2 tbsp","Sake":"2 tbsp"},"steps":[["In a microwave-safe bowl, combine [[2 tbsp]] soy sauce, [[2 tbsp]] mirin, [[2 tbsp]] sake and [[1 tbsp]] sugar. Microwave until hot, stir to dissolve the sugar, and set aside.",null],["On a clean cutting board, lay [[0.75 lb]] chicken thighs smooth side down. Cut slits across the meat every 1/2 inch without slicing all the way through: deeper on thick parts, skip thin parts.",null],["After each cut, press the meat open and flatten it with your fingers so it is an even thickness.",null],["Season the chicken with [[0.125 tsp]] kosher salt and [[0.125 tsp]] black pepper.",null],["Heat a large frying pan over medium to medium-high heat and add [[1 tbsp]] neutral oil. When it is hot, place the chicken in smooth side down.",null],["Cook for 5 minutes. Press down hard with a spatula for 5-10 seconds to sear, then flip and press again for 5-10 seconds.",5],["Turn the heat to low, cover the pan with a lid, and steam for 3 minutes.",3],["Take off the lid and wipe away the extra grease with a paper towel.",null],["Turn the heat up to medium and pour in the teriyaki sauce. Tilt the pan and keep spooning the sauce over the chicken.",null],["When the chicken is well coated and cooked through, move it to a cutting board.",null],["Keep cooking the sauce in the pan until it is as thick as you like, then pour it into a bowl.",null],["Slice the chicken into bite-sized pieces and put them on a ceramic plate. Sear the top with a kitchen butane torch or under the broiler.",null],["Serve with the sauce drizzled on top, over steamed rice if you like.",null]],"technique":3,"prep":1,"precision":2,"nutrition":{"calories":652,"protein_g":38,"carbs_g":10,"fat_g":47},"video":"https://www.youtube.com/embed/6NkG4Qp0lyc","country":"JP","effort_steps":6,"ingredients":[{"item":"boneless, skinless chicken thighs","qty":0.75,"qtyMax":1,"unit":"lb","group":"Chicken"},{"item":"Diamond Crystal kosher salt","qty":0.125,"unit":"tsp","group":"Chicken"},{"item":"freshly ground black pepper","qty":0.125,"unit":"tsp","group":"Chicken"},{"item":"neutral oil","qty":1,"unit":"tbsp","group":"Chicken"},{"item":"soy sauce","qty":2,"unit":"tbsp","group":"Teriyaki Sauce"},{"item":"mirin","qty":2,"unit":"tbsp","group":"Teriyaki Sauce"},{"item":"sake","qty":2,"unit":"tbsp","group":"Teriyaki Sauce"},{"item":"sugar","qty":1,"unit":"tbsp","group":"Teriyaki Sauce"}]}'::jsonb),
('www-justonecookbook-com-omurice-japanese-omelette-rice', 'Omurice (Japanese Omelette Rice)', 'Japanese', 'Just One Cookbook', 'https://www.justonecookbook.com/omurice-japanese-omelette-rice/', 25, 2, 2, 2, 4, 17, 46, array['rice', 'eggs', 'chicken', 'onion', 'butter', 'ketchup', 'peas']::text[], '{"title":"Omurice (Japanese Omelette Rice)","cuisine":"Japanese","source":"Just One Cookbook","url":"https://www.justonecookbook.com/omurice-japanese-omelette-rice/","minutes":25,"servings":2,"key":["Rice","Eggs","Chicken thighs","Onion","Butter","Ketchup","Frozen peas"],"minor":["Worcestershire sauce","Black pepper"],"amounts":{"Rice":"1 3/4 cups cooked short-grain","Eggs":"4 large","Chicken thighs":"3 oz boneless, skinless","Onion":"1/4 yellow onion","Butter":"3 tbsp unsalted (divided)","Ketchup":"5 tbsp plus garnish","Frozen peas":"1 tbsp cooked"},"steps":[["Warm [[1.75 cups]] day-old or frozen cooked rice in the microwave. If you''re using fresh rice, spread it on a baking sheet to cool and let extra moisture evaporate.",null],["On a clean cutting board, finely dice [[0.25]] yellow onion into 1/8-inch pieces.",null],["Slice [[3 oz]] chicken thigh at an angle into 1/2-inch strips, then cut the strips into 1/2-inch squares so they cook evenly.",null],["Melt [[1 tbsp]] butter in a large frying pan over medium heat. Add the onion and sauté until translucent and tender.",null],["Add the chicken and season with [[0.25 tsp]] salt and some black pepper. Cook until it is no longer pink.",null],["Turn the heat down slightly. Add [[5 tbsp]] ketchup and [[1 tsp]] Worcestershire sauce and stir until the extra moisture cooks off.",null],["Add the warm rice to the pan, breaking up clumps with cutting motions of your spatula.",null],["Season with [[0.25 tsp]] salt and black pepper. Add [[1 tbsp]] green peas and toss until warmed through. Take the pan off the heat and divide the rice into 2 portions.",null],["For the first omelette, crack [[2]] eggs into a small bowl. Beat them in a zigzag motion, stir in [[0.25 tsp]] salt, then pour through a fine-mesh strainer.",null],["Lay a damp cloth on the counter. Melt [[1 tbsp]] butter in an 8-inch nonstick pan over medium heat, coating the whole surface. Drop in a bit of egg: if it sizzles, the pan is ready. Pour in the strained eggs.",null],["Quickly stir the eggs in a spiral with chopsticks while shaking the pan, tilting it so runny egg spreads to the edges. Stop once the eggs are half-cooked, and level out the curds.",null],["Place one portion of chicken rice in the center of the omelette and turn off the heat.",null],["Set the pan on the damp cloth to cool. Tilt the pan away from you and fold the near side of the egg over the rice. Slide the omelette to the far edge and wrap the far side over the rice.",null],["Tilt a plate against the edge of the pan, flip the pan, and turn the omelette onto the plate seam side down.",null],["Shape the omelette into an oval using a paper towel and your hands. Top with a dollop of ketchup or a zigzag drizzle.",null],["Repeat steps 9-15 with the remaining [[2]] eggs, [[0.25 tsp]] salt, [[1 tbsp]] butter and the second portion of rice.",null],["Store leftovers in an airtight container in the fridge for up to 3 days or in the freezer for up to 1 month.",null]],"technique":2,"prep":2,"precision":4,"nutrition":{"calories":609,"protein_g":28,"carbs_g":39,"fat_g":37},"video":"https://www.youtube.com/embed/mibRQZm8wXw","country":"JP","effort_steps":7,"ingredients":[{"item":"cooked Japanese short-grain rice","qty":1.75,"unit":"cup","note":"2 servings, 330 g; day-old, preferably","group":"Chicken Rice"},{"item":"boneless, skinless chicken thigh","qty":3,"unit":"oz","group":"Chicken Rice"},{"item":"yellow onion","qty":0.25,"note":"4 oz, 113 g","group":"Chicken Rice"},{"item":"green peas","qty":1,"unit":"tbsp","note":"cooked","group":"Chicken Rice"},{"item":"ketchup","qty":5,"unit":"tbsp","note":"plus more for garnish; Kagome brand recommended","group":"Chicken Rice"},{"item":"Worcestershire sauce","qty":1,"unit":"tsp","group":"Chicken Rice"},{"item":"Diamond Crystal kosher salt","qty":0.5,"unit":"tsp","note":"divided","group":"Chicken Rice"},{"item":"freshly ground black pepper","group":"Chicken Rice"},{"item":"unsalted butter","qty":1,"unit":"tbsp","group":"Chicken Rice"},{"item":"eggs","qty":4,"unit":"large","note":"50 g each without shell; divided","group":"Omelettes"},{"item":"Diamond Crystal kosher salt","qty":0.5,"unit":"tsp","note":"divided","group":"Omelettes"},{"item":"unsalted butter","qty":2,"unit":"tbsp","note":"divided","group":"Omelettes"}]}'::jsonb),
('www-justonecookbook-com-tori-soboro-donburi', 'Soboro Don (Ground Chicken Bowl)', 'Japanese', 'Just One Cookbook', 'https://www.justonecookbook.com/tori-soboro-donburi/', 30, 2, 2, 1, 2, 9, 37, array['chicken', 'eggs', 'rice', 'soy sauce', 'ginger', 'peas']::text[], '{"title":"Soboro Don (Ground Chicken Bowl)","cuisine":"Japanese","source":"Just One Cookbook","url":"https://www.justonecookbook.com/tori-soboro-donburi/","minutes":30,"servings":2,"key":["Ground chicken","Eggs","Rice","Soy sauce","Ginger","Frozen peas"],"minor":["Sake","Mirin","Pickled red ginger (optional)"],"amounts":{"Ground chicken":"1/2 lb","Eggs":"3 large","Rice":"2 servings (3 1/3 cups cooked)","Soy sauce":"2 1/2 tbsp","Ginger":"1 tsp grated","Frozen peas":"2 tbsp cooked"},"steps":[["Grate [[1 inch]] fresh ginger to get about 1 tsp, keeping the juice.",null],["In a medium saucepan with the heat OFF, combine the ginger, [[0.5 lb]] ground chicken, [[1 tbsp]] sake, [[1 tbsp]] mirin, [[1 tbsp]] sugar (up to 1 1/2 tbsp) and [[2.5 tbsp]] soy sauce.",null],["Turn the heat to medium-low. Using 3 pairs of cooking chopsticks, stir constantly, breaking the meat into fine crumbles, for 3-4 minutes.",3],["Keep cooking until the liquid evaporates and the chicken looks glossy and glazed, about 2-3 minutes. Take it off the heat.",2],["In a second saucepan with the heat OFF, combine [[3 large]] eggs, [[1 tbsp]] sugar and [[0.25 tsp]] salt. Beat with chopsticks until the sugar is completely dissolved.",null],["Turn the heat to medium-low. Cook the eggs, stirring constantly with 3 chopsticks and scraping cooked egg from the bottom and sides.",null],["Cook until the eggs are barely set and look moist, not dry, then take them off the heat right away.",null],["Divide [[3.333 cups]] cooked rice between two bowls. Spoon the chicken over one half of each bowl and the eggs over the other half.",null],["Arrange [[2 tbsp]] green peas down the middle, and garnish with pickled red ginger if you like.",null]],"technique":2,"prep":1,"precision":2,"nutrition":{"calories":575,"protein_g":30,"carbs_g":45,"fat_g":28},"video":null,"country":"JP","effort_steps":5,"ingredients":[{"item":"ground chicken","qty":0.5,"unit":"lb","group":"Chicken"},{"item":"fresh ginger","qty":1,"unit":"inch","note":"1 tsp grated with juice","group":"Chicken"},{"item":"sake","qty":1,"unit":"tbsp","group":"Chicken"},{"item":"mirin","qty":1,"unit":"tbsp","group":"Chicken"},{"item":"sugar","qty":1,"qtyMax":1.5,"unit":"tbsp","group":"Chicken"},{"item":"soy sauce","qty":2.5,"unit":"tbsp","group":"Chicken"},{"item":"eggs","qty":3,"unit":"large","note":"50 g each without shell","group":"Scrambled Eggs"},{"item":"sugar","qty":1,"unit":"tbsp","group":"Scrambled Eggs"},{"item":"Diamond Crystal kosher salt","qty":0.25,"unit":"tsp","group":"Scrambled Eggs"},{"item":"cooked Japanese short-grain rice","qty":3.333,"unit":"cup","note":"2 servings, 500 g","group":"For Serving"},{"item":"green peas","qty":2,"unit":"tbsp","note":"cooked","group":"For Serving"},{"item":"pickled red ginger","note":"optional","group":"For Serving"}]}'::jsonb),
('www-maangchi-com-recipe-gyeranjjim', 'Steamed egg side dish (Gyeranjjim)', 'Korean', 'Maangchi', 'https://www.maangchi.com/recipe/gyeranjjim', 10, 2, 1, 1, 1, 5, 22, array['eggs', 'scallions', 'fish sauce']::text[], '{"title":"Steamed egg side dish (Gyeranjjim)","cuisine":"Korean","source":"Maangchi","url":"https://www.maangchi.com/recipe/gyeranjjim","minutes":10,"servings":2,"key":["Eggs","Scallions","Fish sauce"],"minor":["Salted shrimp sauce (alternative to fish sauce)"],"amounts":{"Eggs":"3","Scallions":"2 green onions, chopped","Fish sauce":"3 tsp (or salted shrimp sauce)"},"steps":[["On a clean cutting board, chop [[2]] green onions.",null],["In a microwavable bowl, put [[3]] eggs, [[0.5 cup]] water, [[3 tsp]] salted shrimp sauce (or fish sauce) and the green onions. Mix well.",null],["Put the bowl in the microwave and cook for 5 minutes.",5],["No microwave? Pour about 3-4 cups of water into a large pot and set the bowl of egg mixture in the center. Close the lid and steam for about 15 minutes over medium heat.",15],["Serve with rice.",null]],"technique":1,"prep":1,"precision":1,"nutrition":null,"video":"https://www.youtube.com/watch?v=-IicuyDgRyw","country":"KR","effort_steps":4,"ingredients":[{"item":"eggs","qty":3},{"item":"water","qty":0.5,"unit":"cup"},{"item":"salted shrimp sauce (saeujeot)","qty":3,"unit":"tsp","note":"or 3 teaspoons fish sauce"},{"item":"green onions","qty":2,"note":"chopped"}]}'::jsonb),
('www-maangchi-com-recipe-gyeran-mari', 'Korean rolled omelette (Gyeran-mari)', 'Korean', 'Maangchi', 'https://www.maangchi.com/recipe/gyeran-mari', 20, 2, 2, 2, 4, 13, 43, array['eggs', 'onion', 'bell peppers', 'carrots']::text[], '{"title":"Korean rolled omelette (Gyeran-mari)","cuisine":"Korean","source":"Maangchi","url":"https://www.maangchi.com/recipe/gyeran-mari","minutes":20,"servings":2,"key":["Eggs","Onion","Bell peppers","Carrots"],"minor":["Black or white pepper"],"amounts":{"Eggs":"4 large","Onion":"1/2 medium, minced","Bell peppers":"1 tbsp minced green (optional)","Carrots":"1 tbsp minced, or red bell pepper (optional)"},"steps":[["On a clean cutting board, mince [[0.5 medium]] onion. If using them, mince [[1 tbsp]] green bell pepper and [[1 tbsp]] red bell pepper (or carrot).",null],["Crack [[4 large]] eggs into a bowl, add [[1 tsp]] kosher salt, and beat with a whisk or fork.",null],["Into the same bowl, stir in the onion, [[0.25 tsp]] black (or white) pepper and the bell peppers if using. Mix with a spoon.",null],["Put [[1 tbsp]] vegetable oil (up to 2 tbsp) in a small bowl and have a basting brush ready.",null],["Heat a large non-stick skillet over medium heat. Once it is hot, lower the heat to medium-low or low and brush the skillet with oil.",null],["Spoon about 1/3 of the egg mixture into the skillet and spread it evenly into a thin rectangle. Cook 1-2 minutes, until the bottom is set but the top is still a little runny.",1],["Lift the right edge with a spatula and roll the egg up from right to left. Brush oil on the cleared part of the skillet and move the roll back to the right side.",null],["Spoon half of the remaining egg into the skillet just left of the roll, so it runs into the roll''s bottom edge and extends it. Cook 1-2 minutes, until set on the bottom but still a bit runny on top.",1],["Turn the roll over onto the new egg layer and roll it up from right to left. Brush the skillet with the remaining oil and push the roll back to the far right side.",null],["Add the rest of the egg mixture the same way. When it has set, roll it up again from right to left into a long, even rectangle.",null],["Turn the heat to low and cook, turning the roll so all 4 sides cook evenly, 3-4 minutes.",3],["Take the skillet off the heat and move the omelette to a cutting board. To make it a neater rectangle, wrap it in a gimbap mat and press it into shape with your hands.",null],["Let it cool for 5 minutes, then cut crosswise into 1/2 or 3/4 inch slices and serve with rice.",5]],"technique":2,"prep":2,"precision":4,"nutrition":null,"video":"https://www.youtube.com/watch?v=kN89ewZjOR8","country":"KR","effort_steps":6,"ingredients":[{"item":"eggs","qty":4,"unit":"large"},{"item":"kosher salt","qty":1,"unit":"tsp"},{"item":"onion","qty":0.5,"unit":"medium","note":"chopped, minced"},{"item":"ground black (or white) pepper","qty":0.25,"unit":"tsp"},{"item":"green bell pepper","qty":1,"unit":"tbsp","note":"minced, optional"},{"item":"red bell pepper (or carrot)","qty":1,"unit":"tbsp","note":"minced, optional"},{"item":"vegetable oil","qty":1,"qtyMax":2,"unit":"tbsp"}]}'::jsonb),
('www-maangchi-com-recipe-dakbokkeumtang', 'Dakbokkeumtang (Spicy Braised Chicken Breasts)', 'Korean', 'Maangchi', 'https://www.maangchi.com/recipe/dakbokkeumtang', 60, 3, 4, 2, 2, 12, 59, array['chicken', 'potatoes', 'onion', 'soy sauce', 'gochujang', 'garlic', 'scallions']::text[], '{"title":"Dakbokkeumtang (Spicy Braised Chicken Breasts)","cuisine":"Korean","source":"Maangchi","url":"https://www.maangchi.com/recipe/dakbokkeumtang","minutes":60,"servings":3,"key":["Chicken breast","Potatoes","Onion","Soy sauce","Gochujang","Garlic","Scallions"],"minor":["Gochugaru","Ginger","Apple","Milk","Green chili pepper","Black pepper"],"amounts":{"Chicken breast":"1 lb (about 2 large)","Potatoes":"8 oz","Onion":"1 medium","Soy sauce":"2 tbsp","Gochujang":"2 tbsp","Garlic":"4 cloves","Scallions":"2 green onions"},"steps":[["On a clean cutting board, cut [[1 lb]] chicken breasts crosswise into 2 1/2 inch chunks (about 4 pieces per breast).",null],["Make 1-inch-deep slits in each chunk, 1/2 inch apart. Sprinkle [[0.5 tsp]] kosher salt evenly over the chicken and into the slits.",null],["Put the chicken in a bowl, add [[0.25 cup]] milk and gently mix. Cover and refrigerate for at least 30 minutes and up to 2 hours.",30],["While the chicken marinates, prep the vegetables: peel, core and thinly slice [[1 small]] apple; peel [[8 oz]] potato and cut it into 1/2 to 1 inch chunks; slice [[1 medium]] onion; chop [[1]] green chili pepper; cut [[2]] green onions into 1-inch pieces.",null],["Mince [[4 cloves]] garlic and [[1 tsp]] peeled ginger.",null],["In a small bowl, mix [[2 tbsp]] soy sauce, [[1 tbsp]] gochugaru, [[2 tbsp]] gochujang, the garlic, the ginger and [[0.5 tsp]] black pepper with a spoon to make the seasoning paste.",null],["Put the chicken on the cutting board, slit side up, and push apple slices into each slit.",null],["Move the chicken into a 9 1/2-inch pan (2 1/2 inches deep). Repeat with the rest of the chicken and apple slices.",null],["Add the seasoning paste and [[2.5 cups]] water to the pan. Cover and cook for 15 minutes over medium-high heat.",15],["Add the potato, onion and green chili pepper and stir gently. Cover, turn the heat down to medium, and cook 15 minutes more.",15],["Add the green onions, turn the heat up to medium-high, and stir for 1 minute until it is bubbling vigorously.",1],["Take it off the heat and serve right in the pan with rice, kimchi and side dishes.",null]],"technique":4,"prep":2,"precision":2,"nutrition":null,"video":"https://www.youtube.com/watch?v=T7icxr899qc","country":"KR","effort_steps":5,"ingredients":[{"item":"chicken breasts","qty":1,"unit":"lb","note":"about 2 large chicken breasts"},{"item":"milk","qty":0.25,"unit":"cup"},{"item":"kosher salt","qty":0.5,"unit":"tsp"},{"item":"apple","qty":1,"unit":"small","note":"peeled, cored, and sliced thinly (about 1 cup)"},{"item":"potato","qty":8,"unit":"oz","note":"peeled and cut into 1/2 to 1 inch thick bite sized chunks"},{"item":"onion","qty":1,"unit":"medium","note":"6 ounces, sliced"},{"item":"green chili pepper","qty":1,"note":"chopped"},{"item":"green onions","qty":2,"note":"cut into 1 inch long"},{"item":"soy sauce","qty":2,"unit":"tbsp","group":"Seasoning Paste"},{"item":"Korean hot pepper flakes (gochugaru)","qty":1,"unit":"tbsp","group":"Seasoning Paste"},{"item":"hot pepper paste (gochujang)","qty":2,"unit":"tbsp","group":"Seasoning Paste"},{"item":"garlic","qty":4,"unit":"clove","note":"minced","group":"Seasoning Paste"},{"item":"ginger","qty":1,"unit":"tsp","note":"peeled, minced","group":"Seasoning Paste"},{"item":"ground black pepper","qty":0.5,"unit":"tsp","group":"Seasoning Paste"}]}'::jsonb),
('hungryinthailand-com-chicken-thai-fried-rice', 'Chicken Thai Fried Rice (Khao Pad Gai)', 'Thai', 'Hungry in Thailand', 'https://hungryinthailand.com/chicken-thai-fried-rice/', 20, 1, 2, 2, 2, 13, 39, array['rice', 'chicken', 'eggs', 'garlic', 'onion', 'carrots', 'soy sauce']::text[], '{"title":"Chicken Thai Fried Rice (Khao Pad Gai)","cuisine":"Thai","source":"Hungry in Thailand","url":"https://hungryinthailand.com/chicken-thai-fried-rice/","minutes":20,"servings":1,"key":["Rice","Chicken breast","Eggs","Garlic","Onion","Carrots","Soy sauce"],"minor":["Chinese broccoli","Rosdee seasoning powder","White pepper","Cucumber","Lime wedge"],"amounts":{"Rice":"190 g cooked jasmine","Chicken breast":"100 g, thinly sliced","Eggs":"1","Garlic":"2 cloves","Onion":"30 g","Carrots":"30 g diced","Soy sauce":"1/2 tbsp light"},"steps":[["On a clean cutting board, mince [[2 cloves]] garlic and dice [[30 g]] onion.",null],["Thinly slice [[100 g]] chicken into bite-sized pieces.",null],["Slice the stems of [[50 g]] Chinese broccoli and roughly chop the leaves, then dice [[30 g]] carrots. Keep the veggies together for later.",null],["Measure out [[190 g]] cooked jasmine rice. Chilled day-old rice works best.",null],["Heat [[1 tbsp]] oil in a wok over medium-high heat.",null],["Add the garlic and onion to the wok and stir-fry until fragrant and slightly golden.",null],["Add the chicken to the wok and stir-fry until it is almost cooked through and lightly browned.",null],["Push the chicken to one side of the wok. Add the remaining [[1 tbsp]] oil and crack in [[1]] egg.",null],["Let the egg cook slightly, then scramble it and mix it in with the chicken.",null],["Toss the rice into the wok and break up any clumps with the back of your spatula. Stir everything together.",null],["Season the rice with [[1 tsp]] rosdee seasoning powder, [[0.5 tbsp]] light soy sauce, [[1 pinch]] salt, [[1 pinch]] white pepper and [[1 tsp]] sugar.",null],["Add the Chinese broccoli and carrots and stir-fry for another 1-2 minutes, until they are slightly softened but still crisp.",1],["Serve hot with cucumber slices, a lime wedge, and prik nam pla if you want a spicy kick.",null]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":486,"protein_g":25,"carbs_g":62,"fat_g":15},"video":null,"country":"TH","effort_steps":6,"ingredients":[{"item":"oil","qty":2,"unit":"tbsp","note":"or 30 ml"},{"item":"garlic","qty":2,"unit":"clove","note":"minced"},{"item":"onions","qty":30,"unit":"g","note":"diced"},{"item":"chicken","qty":100,"unit":"g","note":"thinly sliced"},{"item":"egg","qty":1},{"item":"cooked jasmine rice","qty":190,"unit":"g","note":"preferably chilled day-old rice"},{"item":"rosdee seasoning powder","qty":1,"unit":"tsp","note":"or 4 g"},{"item":"light soy sauce","qty":0.5,"unit":"tbsp","note":"or 7 ml"},{"item":"salt","qty":1,"unit":"pinch"},{"item":"white pepper","qty":1,"unit":"pinch"},{"item":"white sugar","qty":1,"unit":"tsp","note":"or 4 g"},{"item":"Chinese broccoli","qty":50,"unit":"g","note":"stems sliced and leaves roughly chopped"},{"item":"carrots","qty":30,"unit":"g","note":"diced"}]}'::jsonb),
('hot-thai-kitchen-com-garlic-pepper-chicken', 'Thai Garlic Pepper Chicken (Gai Pad Gratiem)', 'Thai', 'Hot Thai Kitchen', 'https://hot-thai-kitchen.com/garlic-pepper-chicken', 25, 3, 2, 2, 2, 11, 38, array['chicken', 'garlic', 'soy sauce', 'oyster sauce', 'fish sauce']::text[], '{"title":"Thai Garlic Pepper Chicken (Gai Pad Gratiem)","cuisine":"Thai","source":"Hot Thai Kitchen","url":"https://hot-thai-kitchen.com/garlic-pepper-chicken","minutes":25,"servings":3,"key":["Chicken breast","Garlic","Soy sauce","Oyster sauce","Fish sauce"],"minor":["Golden Mountain sauce","Black soy sauce","White pepper","Black pepper","Cilantro stems"],"amounts":{"Chicken breast":"500 g breast or thigh, sliced 1 cm","Garlic":"8 cloves, chopped","Soy sauce":"1 tbsp","Oyster sauce":"1 tbsp","Fish sauce":"1 tsp"},"steps":[["On a clean cutting board, cut [[500 g]] chicken into 1-cm thick slices.",null],["Chop [[8 cloves]] garlic and [[7-8]] cilantro stems, keeping them in separate piles.",null],["In a new bowl, mix the chicken with [[1 tbsp]] oyster sauce, [[1 tbsp]] soy sauce, [[1 tsp]] Golden Mountain sauce, [[1 tsp]] fish sauce, [[1/4 tsp]] white pepper and [[1/4 tsp]] black pepper. Set it aside while you fry the garlic.",null],["Put the chopped garlic in a small pot or wok and pour in just enough vegetable oil to cover it.",null],["Fry the garlic over low heat (gentle bubbling) until it turns golden brown and the bubbling has mostly stopped, about 5 minutes.",5],["Drain the garlic from the oil, and save the oil - you will cook with it.",null],["In a wok, heat about [[2 tbsp]] of the garlic oil over high heat.",null],["While it heats, pour a tablespoon or so of the remaining garlic oil into the bowl of marinated chicken and stir to coat.",null],["When the oil is hot, add the chicken and [[1 1/2 tsp]] sugar to the wok, then stir until the chicken is cooked.",null],["Stir in half of the fried garlic and the chopped cilantro stems, then take the wok off the heat.",null],["Just before serving, sprinkle the remaining fried garlic over the top. Serve with jasmine rice.",null]],"technique":2,"prep":2,"precision":2,"nutrition":null,"video":null,"country":"TH","effort_steps":5,"ingredients":[{"item":"chicken breast or thigh","qty":500,"unit":"g","note":"cut into 1-cm thick slices"},{"item":"garlic","qty":8,"unit":"clove","note":"chopped"},{"item":"oyster sauce","qty":1,"unit":"tbsp"},{"item":"soy sauce","qty":1,"unit":"tbsp"},{"item":"Golden Mountain sauce","qty":1,"unit":"tsp","note":"or substitute regular soy sauce"},{"item":"fish sauce","qty":1,"unit":"tsp"},{"item":"black soy sauce","qty":1,"unit":"tsp","note":"as needed for colour, about 1 tsp"},{"item":"sugar","qty":1.5,"unit":"tsp"},{"item":"ground white pepper","qty":0.25,"unit":"tsp"},{"item":"ground black pepper","qty":0.25,"unit":"tsp"},{"item":"cilantro stems","qty":7,"qtyMax":8,"note":"chopped"},{"item":"water","note":"as needed"}]}'::jsonb),
('grantourismotravels-com-thai-omelette-recipe', 'Thai Omelette (Kai Jeow)', 'Thai', 'Grantourismo', 'https://grantourismotravels.com/thai-omelette-recipe/', 15, 1, 4, 1, 3, 8, 47, array['eggs', 'fish sauce', 'rice', 'scallions']::text[], '{"title":"Thai Omelette (Kai Jeow)","cuisine":"Thai","source":"Grantourismo","url":"https://grantourismotravels.com/thai-omelette-recipe/","minutes":15,"servings":1,"key":["Eggs","Fish sauce","Rice","Scallions"],"minor":["Sriracha sauce"],"amounts":{"Eggs":"2","Fish sauce":"1 tsp","Rice":"jasmine rice to serve","Scallions":"for garnish"},"steps":[["In a wide-brimmed measuring cup with a pouring spout, beat [[2]] eggs and [[1 tsp]] fish sauce until fully combined.",null],["Pour enough vegetable oil into a small wok to reach about 1.5 cm deep, and heat the oil to 190°C.",null],["While the oil heats, set out a serving plate and bowls with jasmine rice so you are ready.",null],["When the oil reaches 190°C, pour in the egg mixture. If the wok is hot enough, the omelette will bubble and puff up.",null],["After around 30 seconds, peek at the underside - it should be golden brown, not dark brown.",0.5],["Using a large strainer, carefully flip the omelette and cook the other side for just a few seconds.",null],["Flip it back so the darker side faces up, then carefully lift it out of the wok onto the serving plate.",null],["Sprinkle with spring onions and add a few dashes of Sriracha sauce.",null]],"technique":4,"prep":1,"precision":3,"nutrition":{"calories":128,"protein_g":11,"carbs_g":1,"fat_g":8},"video":null,"country":"TH","effort_steps":5,"ingredients":[{"item":"eggs","qty":2,"group":"Main"},{"item":"fish sauce","qty":1,"unit":"tsp","group":"Main"},{"item":"spring onions","group":"To Serve"},{"item":"jasmine rice","group":"To Serve"},{"item":"Sriracha sauce","group":"To Serve"}]}'::jsonb),
('www-recipetineats-com-vietnamese-caramelised-pork-bowls', 'Vietnamese Caramelised Pork Bowls', 'Vietnamese', 'RecipeTin Eats', 'https://www.recipetineats.com/vietnamese-caramelised-pork-bowls/', 20, 4, 2, 1, 2, 11, 34, array['pork', 'rice', 'onion', 'garlic', 'ginger', 'fish sauce', 'scallions']::text[], '{"title":"Vietnamese Caramelised Pork Bowls","cuisine":"Vietnamese","source":"RecipeTin Eats","url":"https://www.recipetineats.com/vietnamese-caramelised-pork-bowls/","minutes":20,"servings":4,"key":["Ground pork","Rice","Onion","Garlic","Ginger","Fish sauce","Scallions"],"minor":["Brown sugar","Bird''s eye chili","Cucumber","Tomato"],"amounts":{"Ground pork":"500 g (1 lb)","Rice":"jasmine rice to serve","Onion":"1/2, finely diced","Garlic":"2 cloves","Ginger":"2 tsp grated","Fish sauce":"2 tbsp","Scallions":"green onion for serving"},"steps":[["On a clean cutting board, finely dice [[1/2]] onion.",null],["Grate [[2 tsp]] ginger and mince [[2 cloves]] garlic. If using, deseed and finely chop [[1]] chili.",null],["Finely slice [[1 stem]] green onion and set it aside for serving.",null],["Heat [[1 1/2 tbsp]] oil in a large skillet over high heat.",null],["Add the onion, ginger, garlic and chili to the skillet and cook for 2 minutes.",2],["Add [[500 g]] pork mince and cook for 2 minutes or so until white all over, breaking up the meat with a wooden spoon.",2],["Add [[5 tbsp]] brown sugar and [[2 tbsp]] fish sauce and give it a stir.",null],["Now leave it alone - don''t touch it - until all the juices cook out and the pork starts to caramelise, about 2 minutes.",2],["Stir, then leave it again without stirring for around 30 seconds to get more caramelisation.",0.5],["Repeat the stir-and-wait twice more, until it is caramelised to your taste.",null],["Serve over jasmine or other rice (or vermicelli noodles), garnished with the sliced green onion, with chunks of plain cucumber and carrots on the side.",null]],"technique":2,"prep":1,"precision":2,"nutrition":{"calories":341,"protein_g":22,"carbs_g":17,"fat_g":13},"video":null,"country":"VN","effort_steps":5,"ingredients":[{"item":"cooking oil","qty":1.5,"unit":"tbsp","note":"peanut oil recommended"},{"item":"onion","qty":0.5,"note":"finely diced (~1/2 cup)"},{"item":"ginger","qty":2,"unit":"tsp","note":"grated or minced"},{"item":"garlic","qty":2,"unit":"clove","note":"minced (2 tsp paste)"},{"item":"birds eye or Thai chili","qty":1,"note":"deseeded and finely chopped (optional)"},{"item":"pork mince (ground pork)","qty":500,"unit":"g","note":"1 lb"},{"item":"brown sugar","qty":5,"unit":"tbsp","note":"tightly packed"},{"item":"fish sauce","qty":2,"unit":"tbsp"},{"item":"green onion","qty":1,"unit":"stem","note":"finely sliced","group":"For Serving"},{"item":"jasmine rice or other rice","group":"For Serving"},{"item":"sliced red chilli, tomato, cucumber","note":"optional","group":"For Serving"}]}'::jsonb),
('www-recipetineats-com-vietnamese-caramel-ginger-chicken', 'Vietnamese Caramel Ginger Chicken', 'Vietnamese', 'RecipeTin Eats', 'https://www.recipetineats.com/vietnamese-caramel-ginger-chicken/', 22, 5, 4, 2, 3, 12, 54, array['chicken', 'ginger', 'fish sauce', 'shallot', 'rice']::text[], '{"title":"Vietnamese Caramel Ginger Chicken","cuisine":"Vietnamese","source":"RecipeTin Eats","url":"https://www.recipetineats.com/vietnamese-caramel-ginger-chicken/","minutes":22,"servings":5,"key":["Chicken thighs","Ginger","Fish sauce","Shallots","Rice"],"minor":["Brown sugar","Bird''s eye chili","Cilantro"],"amounts":{"Chicken thighs":"1 kg (2 lb) boneless","Ginger":"1/3 cup julienned","Fish sauce":"3 tbsp","Shallots":"2 eschalots (or 1/2 red onion)","Rice":"jasmine rice to serve"},"steps":[["On a clean cutting board, cut [[1 kg]] chicken thigh fillets into large 5cm/2\" pieces.",null],["If using, deseed and finely mince [[1]] chilli.",null],["In a new bowl, toss the chicken with [[3 tbsp]] fish sauce and the chilli, then set it aside while you prep the rest.",null],["Finely julienne [[1/3 cup]] ginger, and halve then finely slice [[2]] eschallots.",null],["Grab a large non-stick pan (30cm/12\" - it must be large). While the pan is still cold, mix [[3 tbsp]] oil and [[1/4 cup]] brown sugar in it.",null],["Turn the heat to medium high. As soon as the sugar has melted, take the pan off the stove.",null],["Carefully add the chicken to the pan - it will sizzle, so don''t throw it in! Add the ginger and shallots and toss briefly. If the caramel hardens, that''s ok, it will re-melt.",null],["Put the pan back on the stove and stir just until the chicken turns from pink to white all over - not browned, and definitely not cooked through.",null],["Add [[1/2 cup]] boiling water, stir, and bring to a simmer.",null],["Simmer very rapidly, still on medium high (or even high), for 10 to 12 minutes until the liquid reduces right down to a glaze. Stir every now and then while it''s still watery.",10],["Once it has reduced to a glaze, toss regularly so the chicken gets nice colour.",null],["Serve with jasmine rice or other plain rice, garnished with extra chilli slices and fresh coriander if you like.",null]],"technique":4,"prep":2,"precision":3,"nutrition":{"calories":370,"protein_g":39,"carbs_g":14,"fat_g":17},"video":null,"country":"VN","effort_steps":6,"ingredients":[{"item":"skinless chicken thigh fillets","qty":1,"unit":"kg","note":"2 lb, cut into large 5cm/2\" pieces"},{"item":"fish sauce","qty":3,"unit":"tbsp"},{"item":"bird''s eye chilli or Thai chilli","qty":1,"note":"deseeded, finely minced (optional)"},{"item":"vegetable oil","qty":3,"unit":"tbsp"},{"item":"brown sugar","qty":0.25,"unit":"cup","note":"tightly packed"},{"item":"ginger","qty":0.333,"unit":"cup","note":"finely julienned (about 5 cm/2\" thick piece)"},{"item":"eschallots","qty":2,"note":"halved then finely sliced (sub half red onion)"},{"item":"boiling water","qty":0.5,"unit":"cup"},{"item":"fresh coriander/cilantro or green onion slices","note":"recommended","group":"Garnishes & serving"},{"item":"red chilli","note":"finely sliced (optional)","group":"Garnishes & serving"},{"item":"jasmine rice, white rice or other plain rice","group":"Garnishes & serving"}]}'::jsonb),
('indianhealthyrecipes-com-punjabi-egg-curry-anda-curry-dhaba-style', 'Egg Curry (Dhaba Style)', 'Indian', 'Swasthi''s Recipes', 'https://indianhealthyrecipes.com/punjabi-egg-curry-anda-curry-dhaba-style/', 40, 5, 4, 2, 3, 14, 60, array['eggs', 'onion', 'tomatoes', 'garlic', 'butter']::text[], '{"title":"Egg Curry (Dhaba Style)","cuisine":"Indian","source":"Swasthi''s Recipes","url":"https://indianhealthyrecipes.com/punjabi-egg-curry-anda-curry-dhaba-style/","minutes":40,"servings":5,"key":["Eggs","Onion","Canned tomatoes","Ginger garlic paste","Butter"],"minor":["Garam masala","Red chili powder","Turmeric","Coriander powder","Bay leaf","Cinnamon","Cardamom","Green chili","Kasuri methi","Cilantro","Cream (optional)"],"amounts":{"Eggs":"4-5 boiled","Onion":"1 1/4 cups chopped","Canned tomatoes":"1 cup tomatoes, chopped or pureed","Ginger garlic paste":"1 tsp","Butter":"1 tsp ghee"},"steps":[["On a clean cutting board, finely chop [[1 1/4 cups]] onions. (For a smoother curry, the page also allows boiling diced onions in [[2 cups]] water for 4 minutes until transparent, then draining and pureeing them in a blender.)",null],["Finely chop [[1 cup]] tomatoes, chop or slit [[1]] green chilli if using, and finely chop [[1 tbsp]] coriander leaves.",null],["Wipe [[4-5]] boiled eggs dry (or let them air dry) so no moisture is left. Prick each egg 2 to 3 times with a fork so they don''t splatter or burst while frying.",null],["Heat [[1 tsp]] ghee or oil in a nonstick pan and fry the eggs until golden and slightly blistered. Move them to a plate; if you like, sprinkle with 2 to 3 pinches each of chilli powder and garam masala.",null],["In a pan, heat [[2 tbsp]] oil and add [[1 small]] bay leaf, [[2]] cardamoms and [[1 small piece]] cinnamon.",null],["When the spices begin to sizzle, add the onions and green chilli. Saute until the onions are golden and the raw smell has almost gone.",null],["Add [[1 tsp]] ginger garlic paste and saute until the raw smell disappears, about one minute.",1],["Add the tomatoes and saute well until the mixture turns mushy.",null],["Add [[1/2-1 tsp]] red chilli powder, [[1/2-1 tsp]] garam masala, [[1/2-1 tsp]] coriander powder, [[1/8 tsp]] turmeric and [[1/2 tsp]] salt. Saute until a nice aroma comes out and the mixture leaves the sides of the pan.",null],["Pour in [[1-1 1/4 cups]] water and mix well. Cover and cook until the curry thickens and traces of oil appear on the surface.",null],["Taste and adjust the salt. Add [[1/2 tsp]] sugar if needed.",null],["Add the fried eggs and [[1/4 tsp]] kasuri methi to the curry. Mix and simmer for a while, then sprinkle with the chopped coriander leaves.",null],["Optional: pour in [[3-4 tbsp]] cream (or 10 cashews blended with half a cup of water until smooth). Cover and cook for 2 to 3 minutes until the curry thickens.",2],["Serve with roti, naan, paratha or plain rice.",null]],"technique":4,"prep":2,"precision":3,"nutrition":{"calories":200,"protein_g":9,"carbs_g":14,"fat_g":14},"video":null,"country":"IN","effort_steps":7,"ingredients":[{"item":"boiled eggs","qty":4,"qtyMax":5},{"item":"oil","qty":2,"unit":"tbsp"},{"item":"ghee or oil","qty":1,"unit":"tsp"},{"item":"onions","qty":1.25,"unit":"cup","note":"fine chopped or 2 medium onions diced, boiled & pureed"},{"item":"tomatoes","qty":1,"unit":"cup","note":"finely chopped or 3 medium tomatoes pureed"},{"item":"green chilli","qty":1,"note":"optional, chopped or slit"},{"item":"ginger garlic paste","qty":1,"unit":"tsp","note":"or finely minced"},{"item":"salt","qty":0.5,"unit":"tsp","note":"adjust to taste"},{"item":"water","qty":1,"qtyMax":1.25,"unit":"cup","note":"adjust slightly as needed"},{"item":"coriander leaves","qty":1,"unit":"tbsp","note":"chopped finely"},{"item":"kasuri methi (dried fenugreek leaves)","qty":0.25,"unit":"tsp","note":"optional"},{"item":"sugar","qty":0.5,"unit":"tsp","note":"optional"},{"item":"cream","qty":4,"unit":"tbsp","note":"or 10 cashews blended with 1/2 cup water (optional)"},{"item":"bay leaf","qty":1,"unit":"small","group":"Whole Spices (skip if you do not have)"},{"item":"cinnamon","qty":1,"unit":"small piece","group":"Whole Spices (skip if you do not have)"},{"item":"green cardamoms","qty":2,"group":"Whole Spices (skip if you do not have)"},{"item":"red chilli powder","qty":0.5,"qtyMax":1,"unit":"tsp","group":"Spice Powders"},{"item":"garam masala","qty":0.5,"qtyMax":1,"unit":"tsp","group":"Spice Powders"},{"item":"coriander powder","qty":0.5,"qtyMax":1,"unit":"tsp","note":"optional","group":"Spice Powders"},{"item":"turmeric","qty":0.125,"unit":"tsp","group":"Spice Powders"}]}'::jsonb),
('www-indianhealthyrecipes-com-simple-chicken-curry-without-coconut', 'Chicken Curry', 'Indian', 'Swasthi''s Recipes', 'https://www.indianhealthyrecipes.com/simple-chicken-curry-without-coconut/', 50, 3, 4, 2, 3, 15, 61, array['chicken', 'onion', 'tomatoes', 'yogurt', 'garlic']::text[], '{"title":"Chicken Curry","cuisine":"Indian","source":"Swasthi''s Recipes","url":"https://www.indianhealthyrecipes.com/simple-chicken-curry-without-coconut/","minutes":50,"servings":3,"key":["Chicken thighs","Onion","Canned tomatoes","Yogurt","Ginger garlic paste"],"minor":["Garam masala","Kashmiri chili powder","Coriander powder","Turmeric","Green chilies","Bay leaf","Cloves","Cinnamon","Cardamom","Cilantro or mint"],"amounts":{"Chicken thighs":"1/2 kg (1.1 lb) chicken, bone-in preferred","Onion":"1 cup (3 medium), chopped","Canned tomatoes":"1/2 cup (2 medium tomatoes), pureed","Yogurt":"1/4 cup","Ginger garlic paste":"1 tbsp"},"steps":[["On a clean cutting board, finely chop [[1 cup]] onions and slit [[1-2]] green chilies.",null],["Puree or finely chop [[1/2 cup]] tomatoes, and finely chop [[2 tbsp]] coriander or mint leaves.",null],["Heat [[2-3 tbsp]] oil in a deep pan over a medium flame. Add [[1]] bay leaf, [[2 inch]] cinnamon piece, [[4]] cloves and [[3]] green cardamoms.",null],["Stir the onions and chilies into the pan and saute until deep golden, 7 to 8 minutes.",7],["Add [[1 tbsp]] ginger garlic paste and saute until you get a nice aroma, about a minute.",1],["Add the tomatoes, [[1/4 tsp]] turmeric and [[1/2-3/4 tsp]] salt. Mix well and cook until the tomatoes turn soft and mushy.",null],["Turn the heat down to low. Stir in [[1/4 cup]] yogurt, [[1 tsp]] red chili powder, [[1 tsp]] garam masala and [[1 tsp]] coriander powder.",null],["Keep cooking on low heat until the mixture smells good and aromatic.",null],["Add [[1/2 kg]] chicken and the coriander leaves. Fry on medium heat until the chicken turns white or pale, around 3 minutes.",3],["Cover and cook on low heat for 3 to 4 minutes - this is when the chicken soaks up the spice flavours.",3],["Meanwhile, heat up [[1 cup]] water in a separate pot.",null],["Pour just enough hot water into the curry (about [[1/2 cup]]) to make a thick gravy. The chicken lets out moisture as it cooks, so add more only if needed.",null],["Cover and cook on a medium flame until the chicken is soft and the gravy turns thick. Bone-in chicken is done when it falls off the bone easily.",null],["Taste the curry and add more salt if needed. You can also add another [[1/2 tsp]] garam masala if it needs more flavour.",null],["Garnish with coriander leaves, cover, and turn off the heat. Serve with butter naan or jeera rice.",null]],"technique":4,"prep":2,"precision":3,"nutrition":{"calories":417,"protein_g":33,"carbs_g":10,"fat_g":26},"video":null,"country":"IN","effort_steps":6,"ingredients":[{"item":"chicken","qty":0.5,"unit":"kg","note":"1.1 lbs, preferably bone-in, boneless is okay"},{"item":"oil","qty":2,"qtyMax":3,"unit":"tbsp"},{"item":"onions","qty":1,"unit":"cup","note":"3 medium, finely chopped"},{"item":"green chilies","qty":1,"qtyMax":2,"note":"slit, omit for less spicy"},{"item":"ginger garlic paste","qty":1,"unit":"tbsp","note":"or 3/4 inch ginger, 3 cloves garlic minced"},{"item":"tomatoes","qty":0.5,"unit":"cup","note":"2 medium, pureed or finely chopped"},{"item":"yogurt","qty":0.25,"unit":"cup","note":"or 1 1/2 tbsp cashew butter or 12 cashews powdered & pureed with 1/4 cup water"},{"item":"salt","qty":0.5,"qtyMax":0.75,"unit":"tsp","note":"adjust as needed"},{"item":"hot water","qty":0.5,"qtyMax":0.75,"unit":"cup","note":"or light coconut milk"},{"item":"coriander leaves or mint leaves","qty":2,"unit":"tbsp","note":"finely chopped"},{"item":"turmeric powder","qty":0.25,"unit":"tsp","group":"Spice Powders"},{"item":"Kashmiri red chili powder","qty":1,"unit":"tsp","note":"or smoked paprika (1/2 tsp for less spicy)","group":"Spice Powders"},{"item":"garam masala","qty":1,"unit":"tsp","note":"1/2 tsp more if needed, adjust to taste","group":"Spice Powders"},{"item":"coriander powder","qty":1,"unit":"tsp","group":"Spice Powders"},{"item":"bay leaf","qty":1,"note":"or 1 sprig curry leaves","group":"Whole Spices (optional)"},{"item":"cloves","qty":4,"group":"Whole Spices (optional)"},{"item":"cinnamon piece","qty":2,"unit":"inch","group":"Whole Spices (optional)"},{"item":"green cardamom","qty":3,"group":"Whole Spices (optional)"}]}'::jsonb),
('www-teaforturmeric-com-keema-matar', 'Keema Matar (Ground Beef Curry with Peas)', 'Indian', 'Tea for Turmeric', 'https://www.teaforturmeric.com/keema-matar', 45, 4, 4, 2, 2, 13, 59, array['beef', 'peas', 'onion', 'garlic', 'ginger', 'tomatoes', 'yogurt']::text[], '{"title":"Keema Matar (Ground Beef Curry with Peas)","cuisine":"Indian","source":"Tea for Turmeric","url":"https://www.teaforturmeric.com/keema-matar","minutes":45,"servings":4,"key":["Ground beef","Frozen peas","Onion","Garlic","Ginger","Canned tomatoes","Yogurt"],"minor":["Cumin seeds","Coriander powder","Red chili powder","Turmeric","Garam masala","Green chilies","Cilantro","Lemon or lime juice"],"amounts":{"Ground beef":"1 lb","Frozen peas":"1 cup (~130 g), thawed","Onion":"1 medium, finely chopped","Garlic":"5-6 cloves","Ginger":"1-inch piece","Canned tomatoes":"1 medium ripe tomato (~250 g), chopped","Yogurt":"1 tbsp whole-milk"},"steps":[["On a clean cutting board, finely chop [[1 medium]] onion. Crush or very finely chop [[5-6 cloves]] garlic and a [[1-inch piece]] ginger.",null],["Finely chop [[1 medium]] tomato and chop [[1-2]] green chili peppers.",null],["Chop [[1/4 cup]] cilantro leaves, plus a little extra for garnish. Make sure [[1 cup]] frozen peas are thawed.",null],["Heat [[3 tbsp]] oil in a medium pan over high heat. Add [[1 tsp]] cumin seeds and the onion and saute for 8 minutes until golden brown.",8],["Add the garlic and ginger and stir for 1 minute until aromatic.",1],["Add [[1 lb]] ground beef. Cook for 5 minutes, stirring often and breaking the meat into small pieces with a wooden spatula, until it''s no longer pink and the moisture dries up.",5],["Add the tomato, green chili, [[1 tbsp]] yogurt, [[1 tsp]] ground coriander, [[3/4 tsp]] red chili powder, [[1/2 tsp]] turmeric and [[1 1/8 tsp]] salt. Saute for 2 minutes until the tomatoes begin breaking down.",2],["Add [[1/4 cup]] water and let it simmer.",null],["Lower the heat to medium, cover, and cook for 15 minutes, stirring once. If it starts to stick, add another [[1/4 cup]] water.",15],["Uncover and stir in the peas, the optional small green chili, and [[1/2 cup]] water. Cover and cook for 3-5 minutes until the peas are tender.",3],["Add [[1 tsp]] black pepper, [[1/4-1/2 tsp]] garam masala and the chopped cilantro. Saute for 1-2 minutes until the oil separates from the curry.",1],["Taste and adjust the salt and spice. Turn the heat to its lowest setting, cover, and let the flavours settle for 5 minutes.",5],["Turn off the heat, sprinkle with the extra cilantro, and squeeze in [[1/2 tsp]] lemon or lime juice. Serve hot with bread or rice.",null]],"technique":4,"prep":2,"precision":2,"nutrition":{"calories":449,"protein_g":23,"carbs_g":13,"fat_g":34},"video":null,"country":"IN","effort_steps":7,"ingredients":[{"item":"neutral oil","qty":3,"unit":"tbsp","note":"such as grapeseed or avocado","group":"Curry"},{"item":"cumin seeds","qty":1,"unit":"tsp","group":"Curry"},{"item":"onion","qty":1,"unit":"medium","note":"~220 g, finely chopped","group":"Curry"},{"item":"garlic","qty":5,"qtyMax":6,"unit":"clove","note":"crushed or very finely chopped","group":"Curry"},{"item":"ginger","qty":1,"unit":"inch piece","note":"crushed or very finely chopped","group":"Curry"},{"item":"ground beef","qty":1,"unit":"lb","group":"Curry"},{"item":"ripe tomato","qty":1,"unit":"medium","note":"2 small/~250 g, finely chopped","group":"Curry"},{"item":"green chili peppers","qty":1,"qtyMax":2,"note":"such as a small Serrano or Thai chili, chopped","group":"Curry"},{"item":"plain whole-milk yogurt","qty":1,"unit":"tbsp","group":"Curry"},{"item":"ground coriander","qty":1,"unit":"tsp","group":"Curry"},{"item":"mild red chili powder","qty":0.75,"unit":"tsp","note":"or to taste","group":"Curry"},{"item":"turmeric powder","qty":0.5,"unit":"tsp","group":"Curry"},{"item":"kosher salt","qty":1.125,"unit":"tsp","note":"or to taste","group":"Curry"},{"item":"frozen green peas","qty":1,"unit":"cup","note":"~130 g, thawed","group":"After Cooking"},{"item":"mild green chili pepper","qty":1,"unit":"small","note":"such as a Serrano, chopped (optional)","group":"After Cooking"},{"item":"black pepper","qty":1,"unit":"tsp","note":"freshly ground","group":"After Cooking"},{"item":"garam masala","qty":0.25,"qtyMax":0.5,"unit":"tsp","note":"start with 1/4 tsp if store-bought","group":"After Cooking"},{"item":"cilantro leaves","qty":0.25,"unit":"cup","note":"chopped, plus more for garnish","group":"After Cooking"},{"item":"fresh lemon or lime juice","qty":0.5,"unit":"tsp","note":"or serve with wedges","group":"After Cooking"}]}'::jsonb),
('www-themediterraneandish-com-kofta-kebab', 'Kofta Kebab', 'Middle Eastern', 'The Mediterranean Dish', 'https://www.themediterraneandish.com/kofta-kebab/', 28, 10, 3, 3, 3, 14, 52, array['beef', 'lamb', 'onion', 'garlic', 'parsley', 'bread']::text[], '{"title":"Kofta Kebab","cuisine":"Middle Eastern","source":"The Mediterranean Dish","url":"https://www.themediterraneandish.com/kofta-kebab/","minutes":28,"servings":10,"key":["Ground beef","Ground lamb","Onion","Garlic","Parsley","Bread"],"minor":["Allspice","Cayenne","Cardamom","Sumac","Nutmeg","Paprika","Pita","Tahini sauce","Tomato"],"amounts":{"Ground beef":"1 lb (85/15)","Ground lamb":"1/2 lb","Onion":"1 medium yellow","Garlic":"2 cloves","Parsley":"1 bunch (about 2 packed cups leaves)","Bread":"1 slice toasted, soaked and squeezed"},"steps":[["Soak 10 wooden skewers in water for about 30 minutes to 1 hour. If you''re using metal skewers, skip this.",30],["Lightly oil the grates of a gas grill and preheat it to medium-high for about 20 minutes.",20],["On a clean cutting board, quarter [[1 medium]] yellow onion. Pull the stems off [[1 bunch]] parsley.",null],["Toast [[1 slice]] bread until browned, then soak it in water until fully tender.",null],["Get your pita, tomato, onion, tahini sauce and any other sides ready so they''re waiting when the kebabs come off the grill.",null],["Put the onion, [[2 cloves]] garlic and the parsley into the bowl of a food processor. Pulse until finely chopped.",null],["Squeeze all the water out of the soaked bread.",null],["Add [[1 lb]] ground beef, [[1/2 lb]] ground lamb and the bread to the food processor, along with kosher salt, black pepper, [[1 1/2 tsp]] allspice, [[1/2 tsp]] cayenne, [[1/2 tsp]] cardamom, [[1/2 tsp]] sumac, [[1/2 tsp]] nutmeg and [[1/2 tsp]] paprika.",null],["Run the processor until everything is well combined into a pasty meat mixture.",null],["Move the mixture to a large bowl and divide it into 10 equal portions.",null],["Press each portion firmly around a skewer, shaping it into an even log about 1-inch thick. Set each one on a parchment-lined tray.",null],["Place the kebabs on the lightly oiled grill and grill on medium-high heat for 4 minutes on one side.",4],["Turn them over and grill for another 3-4 minutes, or until the inside reaches 160°F.",3],["Serve right away with pita bread, tahini and the fixings you prepared.",null]],"technique":3,"prep":3,"precision":3,"nutrition":{"calories":161,"protein_g":14,"carbs_g":3,"fat_g":10},"video":null,"country":"LB","effort_steps":6,"ingredients":[{"item":"yellow onion","qty":1,"unit":"medium","note":"quartered"},{"item":"garlic","qty":2,"unit":"clove"},{"item":"parsley","qty":1,"unit":"bunch","note":"stems removed (about 2 packed cups parsley leaves)"},{"item":"ground beef","qty":1,"unit":"lb","note":"85/15"},{"item":"ground lamb","qty":0.5,"unit":"lb"},{"item":"bread","qty":1,"unit":"slice","note":"toasted until browned and soaked in water until fully tender"},{"item":"kosher salt"},{"item":"ground black pepper"},{"item":"ground allspice","qty":1.5,"unit":"tsp"},{"item":"cayenne pepper","qty":0.5,"unit":"tsp"},{"item":"ground green cardamom","qty":0.5,"unit":"tsp"},{"item":"ground sumac","qty":0.5,"unit":"tsp"},{"item":"ground nutmeg","qty":0.5,"unit":"tsp"},{"item":"paprika","qty":0.5,"unit":"tsp"},{"item":"pita","note":"to serve"},{"item":"tahini sauce","group":"For the Fixings"},{"item":"tomato wedges","group":"For the Fixings"},{"item":"onion wedges","group":"For the Fixings"},{"item":"parsley","note":"more, for serving","group":"For the Fixings"}]}'::jsonb),
('silkroadrecipes-com-lebanese-lentil-soup', 'Lebanese Lentil Soup (Shorbet Adas)', 'Middle Eastern', 'Silk Road Recipes', 'https://silkroadrecipes.com/lebanese-lentil-soup/', 38, 8, 1, 1, 1, 10, 31, array['lentils', 'rice', 'onion', 'carrots', 'garlic', 'broth', 'lemon']::text[], '{"title":"Lebanese Lentil Soup (Shorbet Adas)","cuisine":"Middle Eastern","source":"Silk Road Recipes","url":"https://silkroadrecipes.com/lebanese-lentil-soup/","minutes":38,"servings":8,"key":["Lentils","Rice","Onion","Carrots","Garlic","Broth","Lemon"],"minor":["Lebanese 7 spice","Turmeric","Black pepper","Scallions","Parsley"],"amounts":{"Lentils":"1 1/2 cups dry red lentils","Rice":"1/2 cup short-grain white","Onion":"1","Carrots":"1 large","Garlic":"2 cloves","Broth":"8 cups vegetable broth or water","Lemon":"1, juiced"},"steps":[["On a clean cutting board, chop [[1]] onion and mince [[2 cloves]] garlic.",null],["Peel and dice [[1 large]] carrot, and juice [[1]] lemon.",null],["For the garnish, finely chop [[2]] green onions and chop [[1/4 cup]] parsley.",null],["In a Dutch oven or large pot, heat [[1 tbsp]] olive oil over medium heat and cook the onion for about 5 minutes.",5],["Add the garlic and cook for another minute.",1],["Stir in [[1 1/2 cups]] red lentils, [[1/2 cup]] rice, the carrot, [[1 1/2 tsp]] Lebanese 7 spice, [[1/2 tsp]] turmeric, [[1/2 tsp]] salt and [[1/2 tsp]] black pepper. Cook until the spices are fragrant, about 2-3 minutes.",2],["Pour in [[8 cups]] water or vegetable broth and bring it to a boil.",null],["Turn the heat to low, cover, and cook until the rice and lentils are fully cooked, about 20 minutes.",20],["Stir in the lemon juice. Serve the soup as is, or pulse it a few times with an immersion blender until it''s as smooth as you like.",null],["Garnish with the green onions, parsley and a lemon slice, and serve warm with pita or your favourite bread.",null]],"technique":1,"prep":1,"precision":1,"nutrition":{"calories":193,"protein_g":10,"carbs_g":34,"fat_g":2},"video":null,"country":"LB","effort_steps":5,"ingredients":[{"item":"olive oil","qty":1,"unit":"tbsp"},{"item":"onion","qty":1,"note":"chopped"},{"item":"garlic","qty":2,"unit":"clove","note":"minced"},{"item":"dry red lentils","qty":1.5,"unit":"cup"},{"item":"short grain white rice","qty":0.5,"unit":"cup"},{"item":"carrot","qty":1,"unit":"large","note":"peeled and diced"},{"item":"Lebanese 7 spice","qty":1.5,"unit":"tsp"},{"item":"turmeric","qty":0.5,"unit":"tsp"},{"item":"kosher salt","qty":0.5,"unit":"tsp"},{"item":"black pepper","qty":0.5,"unit":"tsp"},{"item":"water or vegetable broth","qty":8,"unit":"cup"},{"item":"lemon","qty":1,"note":"juice"},{"item":"green onions","qty":2,"note":"chopped fine","group":"Garnish"},{"item":"parsley","qty":0.25,"unit":"cup","note":"chopped","group":"Garnish"}]}'::jsonb),
('www-themediterraneandish-com-strapatsada-greek-tomato-feta-scrambled-eggs', 'Strapatsada (Greek Tomato Feta Scrambled Eggs)', 'Greek', 'The Mediterranean Dish', 'https://www.themediterraneandish.com/strapatsada-greek-tomato-feta-scrambled-eggs/', 20, 2, 2, 1, 2, 10, 34, array['eggs', 'tomatoes', 'tomato paste', 'feta', 'garlic', 'bread']::text[], '{"title":"Strapatsada (Greek Tomato Feta Scrambled Eggs)","cuisine":"Greek","source":"The Mediterranean Dish","url":"https://www.themediterraneandish.com/strapatsada-greek-tomato-feta-scrambled-eggs/","minutes":20,"servings":2,"key":["Eggs","Cherry tomatoes","Tomato paste","Feta","Garlic","Bread"],"minor":["Fresh parsley","Black pepper"],"amounts":{"Eggs":"5 large","Cherry tomatoes":"1 cup, halved","Tomato paste":"2 tablespoons","Feta":"1/2 cup crumbled","Garlic":"1 clove","Bread":"crusty bread for serving"},"steps":[["On a clean cutting board, halve or quarter the [[1 cup]] cherry or grape tomatoes depending on their size, mince the [[1 clove]] garlic, and mince [[1 tbsp]] fresh parsley.",null],["Crack the [[5 large]] eggs into a medium bowl, add [[0.5 tsp]] salt and [[0.25 tsp]] black pepper, and beat until smooth.",null],["In a large (10 to 12-inch) nonstick skillet, heat [[2 tbsp]] extra virgin olive oil over medium heat.",null],["Add the tomatoes to the skillet and season them lightly with salt. Cook, stirring occasionally, for 5 to 7 minutes, until they soften, start to brown and release their juices.",5],["Add the minced garlic to the same skillet and sauté with the tomatoes just until fragrant, about 1 minute.",1],["Add [[2 tbsp]] tomato paste and [[2 tbsp]] water to the skillet. Stir well and cook for 2 to 3 minutes, until the sauce thickens slightly.",2],["Lower the heat to medium-low and pour the beaten eggs from the bowl into the skillet with the tomato sauce.",null],["Gently stir and cook slowly until the eggs are just set into soft, pillowy curds. Be careful not to overcook them.",null],["Take the pan off the heat. Sprinkle [[0.5 cup]] crumbled feta over the top, then the minced parsley.",null],["Serve right away with thick slices of crusty bread for scooping.",null]],"technique":2,"prep":1,"precision":2,"nutrition":{"calories":392,"protein_g":23,"carbs_g":10,"fat_g":29},"video":null,"country":"GR","effort_steps":5,"ingredients":[{"item":"eggs","qty":5,"unit":"large"},{"item":"salt","qty":0.5,"unit":"tsp"},{"item":"black pepper","qty":0.25,"unit":"tsp","note":"freshly ground"},{"item":"extra virgin olive oil","qty":2,"unit":"tbsp"},{"item":"cherry or grape tomatoes","qty":1,"unit":"cup","note":"halved or quartered depending on size"},{"item":"garlic","qty":1,"unit":"clove","note":"minced"},{"item":"tomato paste","qty":2,"unit":"tbsp"},{"item":"water","qty":2,"unit":"tbsp"},{"item":"feta cheese","qty":0.5,"unit":"cup","note":"crumbled"},{"item":"fresh parsley","qty":1,"unit":"tbsp","note":"minced"},{"item":"crusty bread","note":"for serving"}]}'::jsonb),
('www-themediterraneandish-com-avgolemono-soup-recipe', 'Avgolemono Soup', 'Greek', 'The Mediterranean Dish', 'https://www.themediterraneandish.com/avgolemono-soup-recipe/', 35, 6, 4, 2, 4, 12, 57, array['broth', 'rice', 'chicken', 'eggs', 'lemon', 'carrots', 'garlic']::text[], '{"title":"Avgolemono Soup","cuisine":"Greek","source":"The Mediterranean Dish","url":"https://www.themediterraneandish.com/avgolemono-soup-recipe/","minutes":35,"servings":6,"key":["Chicken broth","Rice","Cooked chicken breast","Eggs","Lemon","Carrots","Garlic"],"minor":["Celery","Green onions","Bay leaves","Fresh parsley"],"amounts":{"Chicken broth":"8 cups low-sodium","Rice":"1 cup","Cooked chicken breast":"2 pieces, shredded (6-8 oz)","Eggs":"2 large","Lemon":"1/2 cup fresh juice","Carrots":"1/2-1 cup finely chopped","Garlic":"2 cloves"},"steps":[["On a clean cutting board, finely chop [[0.5 cup]] each of carrots, celery and green onions (up to 1 cup each if you like more), and finely chop [[2 clove]] garlic.",null],["Shred the [[2]] cooked chicken breast pieces and squeeze [[0.5 cup]] fresh lemon juice. Set both aside.",null],["Heat [[1 tbsp]] olive oil in a large Dutch oven over medium-high heat.",null],["Add the carrots, celery, green onions and garlic to the pot and sauté briefly.",null],["Pour [[8 cups]] low-sodium chicken broth into the pot, add [[2]] bay leaves, and raise the heat to high.",null],["Once it is boiling, add [[1 cup]] rice and season with salt and pepper.",null],["Reduce the heat to medium-low and simmer for 20 minutes, until the rice is tender.",20],["Stir the shredded chicken into the soup.",null],["In a medium bowl, whisk the lemon juice and [[2 large]] eggs together.",null],["While whisking the egg mixture, slowly add 2 ladles-full of hot broth from the pot. This warms (tempers) the eggs so they don''t scramble.",null],["Pour the egg-lemon sauce from the bowl back into the soup pot and stir. Remove the pot from the heat immediately.",null],["Garnish with fresh parsley if you like, and serve hot with bread.",null]],"technique":4,"prep":2,"precision":4,"nutrition":null,"video":null,"country":"GR","effort_steps":5,"ingredients":[{"item":"extra virgin olive oil"},{"item":"carrots","qty":0.5,"qtyMax":1,"unit":"cup","note":"finely chopped"},{"item":"celery","qty":0.5,"qtyMax":1,"unit":"cup","note":"finely chopped"},{"item":"green onions","qty":0.5,"qtyMax":1,"unit":"cup","note":"finely chopped"},{"item":"garlic","qty":2,"unit":"clove","note":"finely chopped"},{"item":"low-sodium chicken broth","qty":8,"unit":"cup"},{"item":"bay leaves","qty":2},{"item":"rice","qty":1,"unit":"cup"},{"item":"salt and pepper"},{"item":"cooked boneless chicken breast pieces","qty":2,"note":"shredded (about 6 to 8 oz store-bought rotisserie chicken)"},{"item":"lemon juice","qty":0.5,"unit":"cup","note":"freshly squeezed"},{"item":"eggs","qty":2,"unit":"large"},{"item":"fresh parsley","note":"for garnish (optional)"}]}'::jsonb),
('www-themediterraneandish-com-spanakorizo-greek-spinach-rice', 'Spanakorizo (Greek Spinach Rice)', 'Greek', 'The Mediterranean Dish', 'https://www.themediterraneandish.com/spanakorizo-greek-spinach-rice/', 60, 6, 2, 2, 2, 12, 49, array['rice', 'spinach', 'onion', 'lemon', 'garlic', 'tomato paste']::text[], '{"title":"Spanakorizo (Greek Spinach Rice)","cuisine":"Greek","source":"The Mediterranean Dish","url":"https://www.themediterraneandish.com/spanakorizo-greek-spinach-rice/","minutes":60,"servings":6,"key":["Rice","Spinach","Onion","Lemon","Garlic","Tomato paste"],"minor":["Dried mint","Dried dill","Feta (garnish)"],"amounts":{"Rice":"1 cup medium grain","Spinach":"1 pound baby spinach","Onion":"1 yellow onion","Lemon":"1, juiced","Garlic":"2 cloves","Tomato paste":"2 tablespoons"},"steps":[["Rinse [[1 cup]] rice well a few times until the water runs clear.",null],["Put the rice in a bowl and add water to cover it by 1 inch. Let it soak for 20 minutes, or until you can easily break a grain between your fingers.",20],["While the rice soaks, chop [[1]] yellow onion and mince [[2 clove]] garlic on a clean cutting board, and juice [[1]] lemon.",null],["Heat [[0.25 cup]] extra virgin olive oil in a braising pan.",null],["Add the onion to the pan and cook for 5 minutes, stirring regularly, until soft and golden brown.",5],["Add [[1 lb]] baby spinach, the lemon juice, the garlic, [[2 tbsp]] tomato paste, and a big pinch of kosher salt and black pepper to the same pan.",null],["Sauté the spinach until just wilted, then stir in [[1.5 tsp]] dried mint and [[1 tsp]] dried dill.",null],["Drain the rice well and add it to the pan with the spinach. Pour in 1 1/2 cups warm water.",null],["Bring to a boil for 3 minutes, until the water reduces a bit.",3],["Turn the heat to low and cover the pan. Let the rice cook undisturbed for 20 minutes, until it is tender and all the liquid is absorbed.",20],["Leave the rice covered off the heat to rest for 5 to 10 minutes.",5],["Fluff the rice with a fork and garnish with feta. You can also add extra finely chopped spinach or minced parsley if you like.",null]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":252,"protein_g":5,"carbs_g":37,"fat_g":10},"video":null,"country":"GR","effort_steps":6,"ingredients":[{"item":"medium grain rice","qty":1,"unit":"cup"},{"item":"extra virgin olive oil","qty":0.25,"unit":"cup"},{"item":"yellow onion","qty":1,"note":"chopped"},{"item":"baby spinach","qty":1,"unit":"lb"},{"item":"lemon","qty":1,"note":"juiced"},{"item":"garlic","qty":2,"unit":"clove","note":"minced"},{"item":"tomato paste","qty":2,"unit":"tbsp"},{"item":"kosher salt"},{"item":"black pepper"},{"item":"dried mint","qty":1.5,"unit":"tsp"},{"item":"dried dill","qty":1,"unit":"tsp"},{"item":"feta","note":"for garnish"}]}'::jsonb),
('www-themediterraneandish-com-greek-bean-soup-fasolada', 'Easy Greek Bean Soup (Fasolada)', 'Greek', 'The Mediterranean Dish', 'https://www.themediterraneandish.com/greek-bean-soup-fasolada/', 30, 6, 1, 2, 1, 12, 32, array['white beans', 'broth', 'onion', 'garlic', 'celery', 'lemon']::text[], '{"title":"Easy Greek Bean Soup (Fasolada)","cuisine":"Greek","source":"The Mediterranean Dish","url":"https://www.themediterraneandish.com/greek-bean-soup-fasolada/","minutes":30,"servings":6,"key":["Canned cannellini beans","Broth","Onion","Garlic","Celery","Lemon"],"minor":["Dried oregano","Bay leaf","Cumin","Sweet paprika","Cayenne","Fresh parsley"],"amounts":{"Canned cannellini beans":"3 (15-oz) cans","Broth":"4 1/2 cups chicken or vegetable","Onion":"1 large yellow","Garlic":"2 cloves","Celery":"4 ribs","Lemon":"1, zested and juiced"},"steps":[["On a clean cutting board, chop [[1 large]] yellow onion and [[4 rib]] celery, mince [[2 clove]] garlic, and chop [[0.5 cup]] fresh parsley.",null],["Drain and rinse the [[3 can (15 oz)]] cannellini beans. Zest and juice [[1]] lemon.",null],["Heat [[2 tbsp]] extra virgin olive oil in a heavy pot over medium-high heat.",null],["Add the onion, [[0.5 tsp]] salt and [[0.5 tsp]] black pepper. Cook for 4 minutes over medium-high heat, stirring regularly.",4],["Add the garlic, celery, [[1]] bay leaf and [[1 tsp]] dried oregano to the pot. Cook 5 more minutes, stirring regularly.",5],["Add [[4.5 cups]] broth, the beans, [[0.5 tsp]] cumin, [[0.25 tsp]] sweet paprika and [[0.25 tsp]] cayenne pepper to the pot.",null],["Raise the heat and bring the soup to a rolling boil for 3 minutes.",3],["Reduce the heat to medium-low, cover, and simmer for 10 minutes.",10],["Ladle 2 cups of the soup into a food processor or blender and blend it, then pour it back into the pot.",null],["Simmer another 5 minutes, then remove the pot from the heat.",5],["Stir in about [[0.333 cup]] extra virgin olive oil, the lemon zest, lemon juice and parsley.",null],["Ladle into bowls, top with more olive oil if you like, and serve with rustic bread.",null]],"technique":1,"prep":2,"precision":1,"nutrition":null,"video":null,"country":"GR","effort_steps":5,"ingredients":[{"item":"extra virgin olive oil"},{"item":"yellow onion","qty":1,"unit":"large","note":"chopped"},{"item":"salt","qty":0.5,"unit":"tsp"},{"item":"black pepper","qty":0.5,"unit":"tsp"},{"item":"garlic","qty":2,"unit":"clove","note":"minced"},{"item":"celery","qty":4,"unit":"rib","note":"chopped"},{"item":"dried oregano","qty":1,"unit":"tsp"},{"item":"dried bay leaf","qty":1},{"item":"chicken broth (or vegetable broth)","qty":4.5,"unit":"cup"},{"item":"cannellini beans","qty":3,"unit":"can (15 oz)","note":"drained and rinsed"},{"item":"ground cumin","qty":0.5,"unit":"tsp"},{"item":"sweet paprika","qty":0.25,"unit":"tsp"},{"item":"cayenne pepper","qty":0.25,"unit":"tsp"},{"item":"lemon","qty":1,"note":"zested and juiced"},{"item":"fresh parsley leaves","qty":0.5,"unit":"cup","note":"chopped"}]}'::jsonb),
('www-recipetineats-com-croque-monsieur', 'Croque Monsieur', 'French', 'RecipeTin Eats', 'https://www.recipetineats.com/croque-monsieur/', 30, 2, 4, 2, 3, 17, 54, array['bread', 'ham', 'gruyere', 'milk', 'butter', 'flour', 'cream']::text[], '{"title":"Croque Monsieur","cuisine":"French","source":"RecipeTin Eats","url":"https://www.recipetineats.com/croque-monsieur/","minutes":30,"servings":2,"key":["Bread","Ham","Gruyere","Milk","Butter","Flour","Heavy cream"],"minor":["Dijon mustard","Parmesan","Nutmeg","White pepper"],"amounts":{"Bread":"4 slices sourdough","Ham":"120g smoked ham","Gruyere":"8 slices Swiss or Gruyere (165g) + 1/2 cup shredded Gruyere","Milk":"1/2 cup","Butter":"1.5 tbsp + 30g","Flour":"1.5 tbsp","Heavy cream":"1/2 cup"},"steps":[["Preheat the oven to 390°F (200°C), or 180°C if it''s a fan oven.",null],["Pour [[0.5 cup]] milk and [[0.5 cup]] cream into a saucepan over medium heat. Heat until steaming, but don''t let it boil, then set it aside.",null],["In a separate small saucepan, melt [[1.5 tbsp]] unsalted butter over medium heat, then turn the heat down to low.",null],["Add [[1.5 tbsp]] flour to the melted butter and cook for 3 minutes, stirring almost constantly. Don''t let it brown.",3],["While stirring, pour in half of the warm milk mixture. Once it''s mixed into the flour paste, add the rest of the milk, [[0.125 tsp]] nutmeg, [[0.25 tsp]] salt and [[1 pinch]] white pepper.",null],["Mix for 30 seconds to a minute, until it thickens to a spreadable, soft-butter consistency. Whisk out any lumps, then take the pan off the heat.",null],["Lay [[4 slice]] sourdough bread on a clean board and spread half of the béchamel over them like butter. Save the other half for the topping.",null],["Top two of the bread slices with 2 slices of cheese each (fold as needed), using half of the [[8 slice]] Swiss or gruyere. Spread the cheese with half of the [[4 tsp]] Dijon mustard.",null],["Lay the [[120 g]] ham on top, then spread the ham with the rest of the Dijon mustard.",null],["Top each with the remaining 2 slices of cheese (folding as needed), then close the sandwiches with the other two slices of bread.",null],["Melt [[30 g]] unsalted butter in a skillet over medium to medium-high heat.",null],["Place the sandwiches in the skillet and cook for 2 minutes, pressing down lightly with a spatula, until deep golden brown.",2],["Flip and cook the other side until golden brown, then move the sandwiches to a baking tray.",null],["Spread the remaining béchamel thickly on top of each sandwich. Sprinkle with [[0.5 cup]] shredded gruyere, then [[3 tbsp]] parmesan.",null],["Bake for 15 minutes.",15],["Switch the oven to the grill/broiler and broil for 3 minutes, until the top is golden and bubbling.",3],["Move straight to warmed plates and serve with a knife and fork.",null]],"technique":4,"prep":2,"precision":3,"nutrition":{"calories":1440,"protein_g":67,"carbs_g":83,"fat_g":94},"video":null,"country":"FR","effort_steps":5,"ingredients":[{"item":"milk","qty":0.5,"unit":"cup","group":"Béchamel"},{"item":"cream (pure or heavy/thickened)","qty":0.5,"unit":"cup","group":"Béchamel"},{"item":"unsalted butter","qty":1.5,"unit":"tbsp","note":"25g","group":"Béchamel"},{"item":"flour, plain/all-purpose","qty":1.5,"unit":"tbsp","group":"Béchamel"},{"item":"salt, kosher/cooking salt","qty":0.25,"unit":"tsp","group":"Béchamel"},{"item":"white pepper","qty":1,"unit":"pinch","group":"Béchamel"},{"item":"nutmeg","qty":0.125,"unit":"tsp","note":"preferably freshly ground","group":"Béchamel"},{"item":"sourdough bread","qty":4,"unit":"slice","note":"1.5cm / 3/5\" thick","group":"Sandwich"},{"item":"Swiss or gruyere cheese","qty":8,"unit":"slice","note":"165g / 6 oz, enough for 2 layers per sandwich","group":"Sandwich"},{"item":"ham slices","qty":120,"unit":"g","note":"preferably smoked (4 oz)","group":"Sandwich"},{"item":"Dijon mustard","qty":4,"unit":"tsp","group":"Sandwich"},{"item":"unsalted butter","qty":30,"unit":"g","note":"2 tbsp","group":"Sandwich"},{"item":"gruyere cheese","qty":0.5,"unit":"cup","note":"shredded (packed cup)","group":"Topping"},{"item":"parmesan","qty":3,"unit":"tbsp","note":"finely shredded","group":"Topping"}]}'::jsonb),
('www-recipetineats-com-chicken-fricassee-quick-french-chicken-stew', 'Chicken Fricassée (Quick French Chicken Stew)', 'French', 'RecipeTin Eats', 'https://www.recipetineats.com/chicken-fricassee-quick-french-chicken-stew/', 60, 4, 4, 2, 3, 15, 63, array['chicken', 'mushrooms', 'onion', 'broth', 'cream', 'butter']::text[], '{"title":"Chicken Fricassée (Quick French Chicken Stew)","cuisine":"French","source":"RecipeTin Eats","url":"https://www.recipetineats.com/chicken-fricassee-quick-french-chicken-stew/","minutes":60,"servings":4,"key":["Chicken thighs","Chicken drumsticks","Mushrooms","Onion","Chicken broth","Heavy cream","Butter"],"minor":["Garlic","Flour","White wine","Bay leaf","Thyme","Parsley"],"amounts":{"Chicken thighs":"4 bone-in, skin-on","Chicken drumsticks":"4","Mushrooms":"300g white","Onion":"2 medium brown","Chicken broth":"3 cups low sodium","Heavy cream":"2/3 cup","Butter":"4 tbsp"},"steps":[["On a clean cutting board, halve the [[300 g]] mushrooms if small (or cut into 4 to 6 pieces if large), slice [[2 medium]] brown onions 0.6cm wide, finely mince [[2 clove]] garlic, and chop [[2 tbsp]] parsley.",null],["Pat the [[4]] chicken thighs and [[4]] drumsticks dry with paper towels, then sprinkle with [[1 tsp]] salt and [[0.5 tsp]] black pepper.",null],["Melt [[4 tbsp]] unsalted butter over medium-high heat in a large skillet or heavy-based pot that has a lid.",null],["Add the chicken thighs skin side down and cook for 4 to 5 minutes until golden brown.",4],["Turn the thighs and cook the other side for 1 minute, then move them to a plate.",1],["Brown the drumsticks in the same pot as best you can, about 2 minutes on each of 3 sides, then move them to the plate too.",6],["Add the mushrooms, onion, [[1]] bay leaf and [[3 sprig]] thyme to the pot. Cook for 5 minutes until the mushrooms are lightly golden.",5],["Add the garlic and stir for 30 seconds. Then add [[3 tbsp]] flour and cook for 1 minute.",1],["Pour in [[0.5 cup]] white wine and [[3 cups]] chicken stock, and add [[0.25 tsp]] salt and [[0.25 tsp]] black pepper. Stir, scraping the bottom of the pot to dissolve the brown bits into the sauce.",null],["Put the chicken back into the sauce, skin side up.",null],["Once it comes to a simmer, adjust the heat so it bubbles steadily but not rapidly. Cover with the lid and simmer for 10 minutes.",10],["Remove the lid and let it simmer for another 20 minutes.",20],["Move the chicken to a plate. Add [[0.667 cup]] cream to the pot and stir.",null],["Once the sauce comes up to a simmer, taste it and add more salt if you want.",null],["Return the chicken to the sauce, then take the pot off the stove. Sprinkle with the parsley and serve over mashed potato, rice or short pasta.",null]],"technique":4,"prep":2,"precision":3,"nutrition":{"calories":792,"protein_g":43,"carbs_g":22,"fat_g":57},"video":null,"country":"FR","effort_steps":6,"ingredients":[{"item":"chicken drumsticks","qty":4,"note":"~150g/5oz each","group":"Chicken"},{"item":"chicken thighs","qty":4,"note":"skin-on and bone-in (~250g/8oz each)","group":"Chicken"},{"item":"salt (cooking/kosher salt)","qty":1,"unit":"tsp","group":"Chicken"},{"item":"black pepper","qty":0.5,"unit":"tsp","group":"Chicken"},{"item":"unsalted butter","qty":4,"unit":"tbsp","note":"60g","group":"Chicken"},{"item":"white mushrooms","qty":300,"unit":"g","note":"halved if small, or cut in 4 to 6 if large (10 oz)","group":"Stew"},{"item":"brown onions","qty":2,"unit":"medium","note":"sliced 0.6cm wide","group":"Stew"},{"item":"garlic","qty":2,"unit":"clove","note":"finely minced","group":"Stew"},{"item":"bay leaf","qty":1,"note":"fresh (sub dried)","group":"Stew"},{"item":"thyme","qty":3,"unit":"sprig","note":"or 1/2 tsp dried thyme","group":"Stew"},{"item":"flour, plain/all-purpose","qty":3,"unit":"tbsp","group":"Stew"},{"item":"white wine","qty":0.5,"unit":"cup","note":"preferably chardonnay","group":"Stew"},{"item":"chicken stock, low sodium","qty":3,"unit":"cup","group":"Stew"},{"item":"salt (cooking/kosher salt)","qty":0.25,"unit":"tsp","group":"Stew"},{"item":"black pepper","qty":0.25,"unit":"tsp","group":"Stew"},{"item":"parsley","qty":2,"unit":"tbsp","note":"chopped","group":"Stew"},{"item":"thickened/heavy cream","qty":0.667,"unit":"cup","group":"Stew"}]}'::jsonb),
('www-recipetineats-com-potatoes-au-gratin', 'Potatoes au Gratin (Dauphinoise)', 'French', 'RecipeTin Eats', 'https://www.recipetineats.com/potatoes-au-gratin/', 105, 8, 3, 3, 2, 9, 69, array['potatoes', 'cream', 'gruyere', 'butter', 'garlic']::text[], '{"title":"Potatoes au Gratin (Dauphinoise)","cuisine":"French","source":"RecipeTin Eats","url":"https://www.recipetineats.com/potatoes-au-gratin/","minutes":105,"servings":8,"key":["Potatoes","Heavy cream","Gruyere","Butter","Garlic"],"minor":["Fresh thyme","Black pepper"],"amounts":{"Potatoes":"1.25 kg / 2.5 lb starchy","Heavy cream":"1 1/2 cups","Gruyere":"2 1/2 cups grated","Butter":"30g / 2 tbsp, melted","Garlic":"2 cloves"},"steps":[["Mince [[2 clove]] garlic, melt [[30 g]] unsalted butter, and grate [[2.5 cups]] gruyere cheese.",null],["Put the melted butter, [[1.5 cups]] cream and the garlic in a jug and mix until combined. This is your cream mixture.",null],["Preheat the oven to 350°F (180°C), for both fan and standard ovens.",null],["Peel [[1.25 kg]] potatoes and slice them 1/8\" (3 mm) thick on a clean cutting board, or use a slicer.",null],["Spread 1/3 of the potatoes in a baking dish. Pour over 1/3 of the cream mixture, then scatter with 1/3 of the [[1 tsp]] salt, [[0.25 tsp]] pepper and [[2 tsp]] thyme. Sprinkle with 3/4 cup of the cheese.",null],["Repeat to make a second and third layer in the same dish, but don''t put cheese on the top layer yet (you''ll add it later).",null],["Cover the dish with a lid or foil and bake for 1 hour 15 minutes, or until the potatoes in the middle are soft when tested with a knife. It might take up to 1 1/2 hours.",75],["Remove the foil and top with the remaining cheese. Bake for another 10 to 15 minutes, until golden and bubbly.",10],["Let it stand for 5 minutes before serving.",5]],"technique":3,"prep":3,"precision":2,"nutrition":{"calories":167,"protein_g":6,"carbs_g":14,"fat_g":10},"video":null,"country":"FR","effort_steps":6,"ingredients":[{"item":"cream","qty":1.5,"unit":"cup","note":"full fat"},{"item":"garlic","qty":2,"unit":"clove","note":"minced"},{"item":"unsalted butter","qty":30,"unit":"g","note":"melted (2 tbsp)"},{"item":"starchy potatoes (Russet, Sebago, Maris Piper)","qty":1.25,"unit":"kg","note":"2.5 lb"},{"item":"salt","qty":1,"unit":"tsp"},{"item":"pepper","qty":0.25,"unit":"tsp"},{"item":"gruyere cheese (or colby, cheddar, havarti, tasty)","qty":2.5,"unit":"cup","note":"freshly grated"},{"item":"fresh thyme leaves","qty":2,"unit":"tsp","note":"optional but recommended"}]}'::jsonb),
('downshiftology-com-recipes-one-pan-chicken-and-rice', 'One Pan Chicken and Rice', 'Mediterranean', 'Downshiftology', 'https://downshiftology.com/recipes/one-pan-chicken-and-rice/', 110, 5, 3, 2, 3, 17, 70, array['chicken', 'rice', 'broth', 'spinach', 'onion', 'lemon', 'garlic']::text[], '{"title":"One Pan Chicken and Rice","cuisine":"Mediterranean","source":"Downshiftology","url":"https://downshiftology.com/recipes/one-pan-chicken-and-rice/","minutes":110,"servings":5,"key":["Chicken thighs","Rice","Chicken broth","Spinach","Onion","Lemon","Garlic"],"minor":["Dijon mustard","Dried oregano","Dried thyme","Parsley"],"amounts":{"Chicken thighs":"5 bone-in, skin-on","Rice":"1 cup long-grain white","Chicken broth":"2 cups","Spinach":"2 cups baby spinach","Onion":"1 yellow","Lemon":"2, juiced and zested","Garlic":"5 cloves total"},"steps":[["On a clean cutting board, mince [[3 clove]] garlic for the marinade and [[2 clove]] garlic for the rice (keep them separate). Dice [[1]] yellow onion and roughly chop [[2 cups]] baby spinach.",null],["Juice and zest [[2]] lemons into a bowl. Add [[2 tsp]] Dijon mustard, the 3 cloves of garlic, [[1 tsp]] dried oregano, [[1 tsp]] dried thyme, [[0.5 tsp]] salt, [[0.25 tsp]] black pepper and [[1 tbsp]] olive oil, and stir together.",null],["Place [[5]] chicken thighs in a glass dish, pour the marinade over them and turn each piece to coat.",null],["Cover the dish and marinate in the fridge for at least 30 minutes and up to overnight.",30],["Preheat your oven to 350°F (175°C).",null],["In a large ovenproof skillet, heat [[2 tbsp]] olive oil over medium-high heat.",null],["Lift the chicken out of the marinade (save the leftover marinade for later) and place the thighs skin-side down in the skillet. Cook about 5 minutes, until the skin is golden brown.",5],["Flip the chicken and cook another 5 minutes, then move the thighs to a plate and set aside.",5],["Use tongs to scrape out any browned bits, and soak up some of the fat with a couple of bunched-up paper towels. Leave a little grease in the skillet for the onions.",null],["Add the diced onion to the skillet and cook for 1 to 2 minutes, until it starts to turn translucent.",1],["Add the chopped spinach, the 2 cloves of garlic, [[1 tsp]] dried oregano, [[0.5 tsp]] salt, [[0.25 tsp]] black pepper and the reserved marinade. Stir for about 30 seconds, until the spinach starts to wilt.",null],["Add [[1 cup]] long grain white rice to the skillet and stir well to coat it with the oil.",null],["Pour [[2 cups]] chicken stock into the skillet, stir well, and bring it to a simmer on the stove.",null],["Arrange the chicken thighs on top of the rice, cover the skillet, and bake in the preheated oven for 35 minutes.",35],["Remove the lid, put the skillet back in the oven, and bake about 10 minutes more, until the chicken is cooked through and the rice is tender.",10],["Let it rest for 5 to 10 minutes. The rice will look dark as the spinach and onions rise to the top, so fluff it with a fork to mix everything back together.",5],["Top with chopped parsley and grilled lemon slices or fresh lemon zest, and serve.",null]],"technique":3,"prep":2,"precision":3,"nutrition":{"calories":423,"protein_g":23,"carbs_g":19,"fat_g":29},"video":"https://www.youtube.com/embed/oNXigmY_dIM","country":null,"effort_steps":6,"ingredients":[{"item":"chicken thighs","qty":5,"note":"skin-on and bone-in","group":"Chicken"},{"item":"olive oil","qty":2,"unit":"tbsp","group":"Chicken"},{"item":"lemons","qty":2,"note":"juiced and zested (approx 1/4 cup of juice)","group":"Marinade"},{"item":"Dijon mustard","qty":2,"unit":"tsp","group":"Marinade"},{"item":"garlic","qty":3,"unit":"clove","note":"minced","group":"Marinade"},{"item":"dried oregano","qty":1,"unit":"tsp","group":"Marinade"},{"item":"dried thyme","qty":1,"unit":"tsp","group":"Marinade"},{"item":"salt","qty":0.5,"unit":"tsp","group":"Marinade"},{"item":"black pepper","qty":0.25,"unit":"tsp","group":"Marinade"},{"item":"olive oil","qty":1,"unit":"tbsp","group":"Marinade"},{"item":"yellow onion","qty":1,"note":"diced","group":"Rice"},{"item":"baby spinach","qty":2,"unit":"cup","note":"lightly packed and roughly chopped","group":"Rice"},{"item":"garlic","qty":2,"unit":"clove","note":"minced","group":"Rice"},{"item":"dried oregano","qty":1,"unit":"tsp","group":"Rice"},{"item":"long grain white rice","qty":1,"unit":"cup","group":"Rice"},{"item":"chicken stock","qty":2,"unit":"cup","group":"Rice"},{"item":"salt","qty":0.5,"unit":"tsp","group":"Rice"},{"item":"black pepper","qty":0.25,"unit":"tsp","group":"Rice"},{"item":"parsley","note":"chopped, for garnish","group":"Rice"},{"item":"lemon zest or slices","note":"for garnish","group":"Rice"}]}'::jsonb),
('www-themediterraneandish-com-shrimp-rice-recipe', 'One Pan Shrimp and Rice', 'Mediterranean', 'The Mediterranean Dish', 'https://www.themediterraneandish.com/shrimp-rice-recipe/', 38, 4, 2, 2, 2, 11, 42, array['rice', 'shrimp', 'peas', 'bell peppers', 'onion', 'garlic']::text[], '{"title":"One Pan Shrimp and Rice","cuisine":"Mediterranean","source":"The Mediterranean Dish","url":"https://www.themediterraneandish.com/shrimp-rice-recipe/","minutes":38,"servings":4,"key":["Rice","Frozen shrimp","Frozen peas","Bell pepper","Onion","Garlic"],"minor":["Parsley","Coriander","Aleppo pepper","Cumin","Paprika","Turmeric"],"amounts":{"Rice":"2 cups basmati","Frozen shrimp":"scant 1 pound large, thawed and peeled","Frozen peas":"1 cup","Bell pepper":"1 red","Onion":"1 red","Garlic":"2 cloves"},"steps":[["Rinse [[2 cups]] Basmati rice well and place it in a large bowl. Cover with water and soak for 15 to 20 minutes, until you can easily break a grain. Drain well.",15],["While the rice soaks, chop [[1]] red onion, core and chop [[1]] red bell pepper, mince [[2 clove]] garlic, and chop [[0.5 cup]] packed fresh parsley (plus a little extra for later). Quickly rinse [[1 cup]] frozen peas to separate them.",null],["In a large deep pan with a lid, heat [[3 tbsp]] extra virgin olive oil over medium heat.",null],["Add the onion, bell pepper, garlic, peas and parsley, and season with kosher salt. Cook for about 3 minutes, tossing regularly.",3],["Add [[1 tsp]] coriander, [[0.75 tsp]] Aleppo pepper, [[0.5 tsp]] cumin and [[0.5 tsp]] paprika. Cook another 2 to 3 minutes, tossing occasionally, until the vegetables soften a bit.",2],["Add the drained rice to the pan with a good pinch of kosher salt, then pour in [[2.25 cups]] water.",null],["Bring to a boil until the liquid has reduced by about half. You should be able to see the rice, with the liquid barely covering the top.",null],["Turn the heat to low, cover, and cook for 15 to 20 minutes, until the rice is fully cooked and not hard or chewy.",15],["While the rice cooks, pat [[1 lb]] peeled, deveined shrimp dry and toss with a bit of kosher salt.",null],["Uncover the pan and nestle the shrimp into the rice. Cover and cook 3 to 5 minutes more, until the shrimp is pink and fully cooked.",3],["Garnish with fresh parsley and serve.",null]],"technique":2,"prep":2,"precision":2,"nutrition":null,"video":null,"country":null,"effort_steps":5,"ingredients":[{"item":"Basmati rice","qty":2,"unit":"cup","note":"rinsed"},{"item":"extra virgin olive oil","qty":3,"unit":"tbsp"},{"item":"red onion","qty":1,"note":"chopped"},{"item":"red bell pepper","qty":1,"note":"cored and chopped"},{"item":"garlic","qty":2,"unit":"clove","note":"minced"},{"item":"frozen peas","qty":1,"unit":"cup","note":"rinsed quickly to separate"},{"item":"fresh parsley","qty":0.5,"unit":"cup","note":"packed, chopped, more for later"},{"item":"kosher salt"},{"item":"coriander","qty":1,"unit":"tsp"},{"item":"mild chile pepper (Aleppo pepper flakes recommended)","qty":0.75,"unit":"tsp"},{"item":"cumin","qty":0.5,"unit":"tsp"},{"item":"paprika","qty":0.5,"unit":"tsp"},{"item":"ground turmeric","qty":0.25,"unit":"tsp"},{"item":"water","qty":2.25,"unit":"cup"},{"item":"large shrimp","qty":1,"unit":"lb","note":"scant 1 lb; thawed if frozen, peeled and deveined"}]}'::jsonb),
('www-themediterraneandish-com-baked-shrimp-stew-recipe', 'Easy Mediterranean-Style Shrimp Stew', 'Mediterranean', 'The Mediterranean Dish', 'https://www.themediterraneandish.com/baked-shrimp-stew-recipe/', 35, 6, 3, 2, 2, 12, 47, array['shrimp', 'tomatoes', 'bell peppers', 'onion', 'garlic', 'lemon']::text[], '{"title":"Easy Mediterranean-Style Shrimp Stew","cuisine":"Mediterranean","source":"The Mediterranean Dish","url":"https://www.themediterraneandish.com/baked-shrimp-stew-recipe/","minutes":35,"servings":6,"key":["Frozen shrimp","Canned tomatoes","Bell pepper","Onion","Garlic","Lemon"],"minor":["Coriander","Sumac","Cumin","Red pepper flakes","Cardamom","Parsley","Pine nuts (optional)","Sesame seeds (optional)"],"amounts":{"Frozen shrimp":"2 1/2 lb large","Canned tomatoes":"2 (15-oz) cans diced","Bell pepper":"1","Onion":"1 large red","Garlic":"5 cloves","Lemon":"wedges for serving"},"steps":[["Preheat the oven to 375°F with a rack in the middle position.",null],["On a clean cutting board, chop [[1 large]] red onion, core and chop [[1]] bell pepper, chop [[5 clove]] garlic, and chop [[1 cup]] parsley leaves.",null],["Heat [[2 tbsp]] olive oil in a large skillet until shimmering.",null],["Add the onion, bell pepper and garlic to the skillet and cook 3 to 4 minutes, stirring regularly.",3],["Stir in [[1.5 tsp]] ground coriander, [[1 tsp]] sumac, [[1 tsp]] cumin, [[1 tsp]] red pepper flakes and [[0.5 tsp]] ground cardamom. Cook about 1 minute, until fragrant.",1],["Add [[2 can (15 oz)]] diced tomatoes and [[0.5 cup]] water to the skillet, and season with salt and pepper.",null],["Bring to a boil, then lower the heat and simmer for 10 to 15 minutes.",10],["Transfer the sauce to an oven-safe dish (or keep it in the skillet if it''s large, deep and oven-safe).",null],["Stir [[2.5 lb]] large shrimp into the sauce. Add the parsley, plus [[0.333 cup]] toasted pine nuts and [[0.25 cup]] toasted sesame seeds if using. Cover with a lid or foil.",null],["Bake for 7 to 9 minutes.",7],["Uncover and broil briefly, until the shrimp turn from gray to pink.",null],["Serve with lemon or lime wedges.",null]],"technique":3,"prep":2,"precision":2,"nutrition":null,"video":null,"country":null,"effort_steps":5,"ingredients":[{"item":"extra virgin olive oil"},{"item":"red onion","qty":1,"unit":"large","note":"chopped"},{"item":"bell pepper","qty":1,"note":"cored, chopped"},{"item":"garlic","qty":5,"unit":"clove","note":"chopped"},{"item":"ground coriander","qty":1.5,"unit":"tsp"},{"item":"sumac","qty":1,"unit":"tsp"},{"item":"cumin","qty":1,"unit":"tsp"},{"item":"red pepper flakes","qty":1,"unit":"tsp"},{"item":"ground green cardamom","qty":0.5,"unit":"tsp"},{"item":"diced tomatoes","qty":2,"unit":"can (15 oz)"},{"item":"water","qty":0.5,"unit":"cup"},{"item":"kosher salt and black pepper"},{"item":"large shrimp","qty":2.5,"unit":"lb"},{"item":"parsley leaves","qty":1,"unit":"cup","note":"chopped"},{"item":"pine nuts","qty":0.333,"unit":"cup","note":"toasted, optional"},{"item":"sesame seeds","qty":0.25,"unit":"cup","note":"toasted, optional"},{"item":"lemon or lime wedges","note":"to serve"}]}'::jsonb),
('thishealthytable-com-blog-ful-medames', 'Ful Medames (Egyptian Fava Beans)', 'Middle Eastern', 'This Healthy Table', 'https://thishealthytable.com/blog/ful-medames/', 40, 4, 2, 1, 1, 10, 37, array['fava bean', 'onion', 'garlic']::text[], '{"title":"Ful Medames (Egyptian Fava Beans)","cuisine":"Middle Eastern","source":"This Healthy Table","url":"https://thishealthytable.com/blog/ful-medames/","minutes":40,"servings":4,"key":["Canned fava beans","Onion","Garlic"],"minor":["Cumin","Cherry tomatoes (optional)","Cucumber (optional)","Pita bread (optional)"],"amounts":{"Canned fava beans":"2 (14.5-oz) cans","Onion":"1 medium red","Garlic":"3 cloves"},"steps":[["On a clean cutting board, slice the red onion and mince the [[3 cloves]] of garlic. Drain the [[2 cans (14.5 oz)]] of fava beans in a colander and rinse them under the tap.",null],["Set a large pot or Dutch oven over medium-high heat and add [[1 tbsp]] olive oil.",null],["Once the oil is hot, add the sliced onion and sauté for 7 to 8 minutes, until it starts to brown and caramelize.",7],["Add the minced garlic to the same pot and sauté for 30 seconds.",0.5],["Add [[1 tsp]] cumin, [[1 tsp]] salt and [[1/3 tsp]] black pepper to the pot and stir for 30 seconds, until the spices smell fragrant.",0.5],["Add the drained fava beans and [[1 1/2 cups]] water to the pot. Turn the heat up and bring it to a low boil.",null],["Reduce the heat to a simmer and let it cook for 20 minutes.",20],["Take the pot off the heat and let it cool slightly.",null],["Blend the bean mixture with a blender, immersion blender or food processor until it''s mostly broken down but still slightly chunky.",null],["Serve with cut cherry tomatoes and sliced cucumbers if you like, plus a little more olive oil or a sprinkle of sea salt. Toast some pita bread for dipping.",null]],"technique":2,"prep":1,"precision":1,"nutrition":{"calories":123,"protein_g":4,"carbs_g":19,"fat_g":4},"video":null,"country":"EG","effort_steps":5,"ingredients":[{"item":"olive oil","qty":1,"unit":"tbsp"},{"item":"red onion","qty":1,"unit":"medium","note":"sliced"},{"item":"garlic","qty":3,"unit":"clove","note":"minced"},{"item":"cumin","qty":1,"unit":"tsp"},{"item":"salt","qty":1,"unit":"tsp"},{"item":"black pepper","qty":0.333,"unit":"tsp","note":"freshly ground"},{"item":"fava beans","qty":2,"unit":"can (14.5 oz)","note":"drained and rinsed"},{"item":"water","qty":1.5,"unit":"cup"},{"item":"cherry tomatoes","note":"optional, for serving"},{"item":"cucumbers","note":"sliced, optional, for serving"},{"item":"pita bread","note":"optional, for serving"}]}'::jsonb),
('littlesunnykitchen-com-hashweh-rice', 'Lebanese Hashweh Rice (Spiced Beef and Rice)', 'Middle Eastern', 'Little Sunny Kitchen', 'https://littlesunnykitchen.com/hashweh-rice/', 50, 6, 2, 2, 3, 17, 49, array['beef', 'rice', 'broth', 'onion', 'butter']::text[], '{"title":"Lebanese Hashweh Rice (Spiced Beef and Rice)","cuisine":"Middle Eastern","source":"Little Sunny Kitchen","url":"https://littlesunnykitchen.com/hashweh-rice/","minutes":50,"servings":6,"key":["Ground beef","Rice","Chicken broth","Onion","Butter"],"minor":["Baharat (7 spice)","Cinnamon","Pine nuts","Almonds","Parsley"],"amounts":{"Ground beef":"1 lb lean","Rice":"2 cups basmati","Chicken broth":"3 cups low-sodium","Onion":"1 small yellow","Butter":"2 tbsp ghee or butter"},"steps":[["On a clean cutting board, finely dice the onion and chop [[2 tbsp]] fresh parsley if you''re using it.",null],["Put [[2 cups]] rice in a large bowl and rinse it with water until the water runs clear.",null],["Cover the rinsed rice with water and let it soak for 15 minutes, then drain it well.",15],["In a large heavy pot over medium heat, heat [[1 tbsp]] olive oil and [[1 tbsp]] ghee or butter.",null],["Add the diced onion and cook until soft and translucent, about 3 to 4 minutes.",3],["Add [[1 lb]] ground beef to the pot and season it with [[1/2 tsp]] baharat, [[1/2 tsp]] cinnamon, all [[1/4 tsp]] of the black pepper and [[1 tsp]] salt.",null],["Cook the beef until browned, breaking it up with a spoon. Spoon off any extra grease if needed.",null],["Add the drained rice to the pot with the remaining [[1/2 tsp]] baharat, the remaining [[1/2 tsp]] cinnamon and the rest of the salt (up to [[1/4 tsp]]).",null],["Pour in [[3 cups]] chicken stock so the liquid sits just slightly above the rice. Add a splash more stock if needed.",null],["Turn the heat to medium-high and bring it to a boil. Do not stir once it''s boiling.",null],["Cover the pot tightly, turn the heat to the lowest setting and cook for 15 minutes without lifting the lid.",15],["Take the pot off the heat and let it rest, still covered, for 5 to 10 minutes.",5],["Uncover and gently fluff the rice with a fork.",null],["In a separate skillet over medium heat, heat the remaining [[1 tbsp]] olive oil and [[1 tbsp]] ghee or butter.",null],["Add [[1/4 cup]] almonds to the skillet and toast until lightly golden, then remove them to a plate.",null],["Add [[1/4 cup]] pine nuts to the same skillet and toast until lightly golden, then remove them right away.",null],["Move the rice to a serving dish and top it with the toasted nuts and parsley if using.",null]],"technique":2,"prep":2,"precision":3,"nutrition":{"calories":538,"protein_g":24,"carbs_g":54,"fat_g":25},"video":null,"country":"LB","effort_steps":6,"ingredients":[{"item":"olive oil","qty":2,"unit":"tbsp","note":"divided"},{"item":"ghee or unsalted butter","qty":2,"unit":"tbsp","note":"divided"},{"item":"yellow onion","qty":1,"unit":"small","note":"finely diced"},{"item":"lean ground beef (90% lean) or ground lamb","qty":1,"unit":"lb"},{"item":"basmati rice or any long-grain rice","qty":2,"unit":"cup"},{"item":"low-sodium chicken stock","qty":3,"unit":"cup","note":"plus more if needed"},{"item":"7 spice (baharat)","qty":1,"unit":"tsp","note":"divided"},{"item":"ground cinnamon","qty":1,"unit":"tsp","note":"divided"},{"item":"ground black pepper","qty":0.25,"unit":"tsp"},{"item":"fine salt","qty":1,"qtyMax":1.25,"unit":"tsp","note":"divided"},{"item":"pine nuts","qty":0.25,"unit":"cup"},{"item":"blanched almond halves or slivered almonds","qty":0.25,"unit":"cup"},{"item":"fresh parsley","qty":2,"unit":"tbsp","note":"chopped, optional for garnish"}]}'::jsonb),
('www-themediterraneandish-com-menemen-recipe', 'Perfect Menemen (Turkish Scrambled Eggs with Tomatoes)', 'Middle Eastern', 'The Mediterranean Dish', 'https://www.themediterraneandish.com/menemen-recipe/', 25, 4, 2, 1, 2, 10, 33, array['eggs', 'tomatoes', 'tomato paste', 'onion', 'bell peppers', 'bread']::text[], '{"title":"Perfect Menemen (Turkish Scrambled Eggs with Tomatoes)","cuisine":"Middle Eastern","source":"The Mediterranean Dish","url":"https://www.themediterraneandish.com/menemen-recipe/","minutes":25,"servings":4,"key":["Eggs","Tomatoes","Tomato paste","Onion","Bell pepper","Bread"],"minor":["Aleppo pepper","Dried oregano","Red pepper flakes"],"amounts":{"Eggs":"4 large","Tomatoes":"2 vine-ripe","Tomato paste":"3 tablespoons","Onion":"1 medium yellow","Bell pepper":"1 green","Bread":"1 baguette (optional)"},"steps":[["On a clean cutting board, chop the onion. Core, seed and chop the green pepper, then chop the [[2]] tomatoes.",null],["Crack [[4]] eggs into a new bowl and beat them with a fork.",null],["In a 10-inch skillet, heat [[2 tbsp]] olive oil over medium heat.",null],["Add the onion and pepper, season with kosher salt, and cook 4 to 5 minutes, stirring regularly, until softened. Try not to let the onions brown.",4],["Add the chopped tomatoes and [[3 tbsp]] tomato paste to the skillet. Season with more kosher salt, black pepper, [[1/2 tsp]] oregano and [[1 tsp]] Aleppo pepper.",null],["Cook over medium heat, stirring now and then, until the tomatoes soften but still hold their shape, 5 to 7 minutes.",5],["Push the tomato and pepper mixture to one side of the pan and lower the heat to medium-low.",null],["Pour the beaten eggs into the empty side of the pan and cook briefly, stirring gently as needed, until the eggs are just set.",null],["Fold the tomato mixture into the eggs.",null],["Finish with a drizzle of olive oil, more Aleppo pepper and red pepper flakes if you like. Serve right away with thick slices of bread.",null]],"technique":2,"prep":1,"precision":2,"nutrition":{"calories":165,"protein_g":7,"carbs_g":9,"fat_g":12},"video":null,"country":"TR","effort_steps":4,"ingredients":[{"item":"extra virgin olive oil","qty":2,"unit":"tbsp","note":"plus more to finish"},{"item":"yellow onion","qty":1,"unit":"medium","note":"chopped"},{"item":"green bell pepper (Anaheim or Holland peppers work as well)","qty":1,"note":"cored, seeded and chopped"},{"item":"kosher salt"},{"item":"vine-ripe tomatoes","qty":2,"note":"chopped"},{"item":"tomato paste","qty":3,"unit":"tbsp"},{"item":"black pepper"},{"item":"dried oregano","qty":0.5,"unit":"tsp"},{"item":"Aleppo pepper","qty":1,"unit":"tsp","note":"plus more for later"},{"item":"eggs","qty":4,"unit":"large","note":"beaten"},{"item":"crushed red pepper flakes","note":"optional, for spice"},{"item":"French baguette","qty":1,"note":"thickly sliced, for serving (optional)"}]}'::jsonb),
('www-budgetbytes-com-cajun-chicken-pasta', 'One Pot Creamy Cajun Chicken Pasta', 'Cajun', 'Budget Bytes', 'https://www.budgetbytes.com/cajun-chicken-pasta/', 30, 4, 2, 2, 2, 12, 40, array['chicken', 'pasta', 'tomatoes', 'broth', 'onion', 'cream cheese']::text[], '{"title":"One Pot Creamy Cajun Chicken Pasta","cuisine":"Cajun","source":"Budget Bytes","url":"https://www.budgetbytes.com/cajun-chicken-pasta/","minutes":30,"servings":4,"key":["Chicken breast","Pasta","Canned tomatoes","Chicken broth","Onion","Cream cheese"],"minor":["Smoked paprika","Oregano","Thyme","Garlic powder","Onion powder","Cayenne","Butter","Green onions"],"amounts":{"Chicken breast":"1 lb boneless, skinless","Pasta":"1/2 lb penne","Canned tomatoes":"15 oz fire roasted diced","Chicken broth":"2 cups","Onion":"1 yellow","Cream cheese":"2 oz"},"steps":[["On a clean cutting board, dice the yellow onion and slice the [[3]] green onions. Set them aside.",null],["In a new small bowl, mix [[2 tsp]] smoked paprika, [[1 tsp]] oregano, [[1 tsp]] thyme, [[1/2 tsp]] garlic powder, [[1/2 tsp]] onion powder, [[1/4 tsp]] cayenne, [[1/4 tsp]] black pepper and [[1/4 tsp]] salt. This is your Cajun seasoning.",null],["Cut [[1 lb]] chicken breast into 1/2 to 3/4-inch cubes and put them in a new bowl.",null],["Pour the Cajun seasoning over the chicken and stir until every piece is coated.",null],["Add [[1 tbsp]] olive oil and [[1 tbsp]] butter to a large deep skillet. Heat over medium-high until very hot and the butter is melted and foamy.",null],["Add the seasoned chicken and cook a couple of minutes per side until it has some color. It does not need to be cooked through yet.",null],["Add the diced onion to the skillet and sauté about 2 minutes, until it begins to soften. The moisture from the onion will lift the browned bits off the bottom of the pan.",2],["Add [[1/2 lb]] uncooked penne, [[15 oz]] fire roasted diced tomatoes with their juices, and [[2 cups]] chicken broth to the skillet. Stir until combined.",null],["Cover with a lid and let the broth come to a boil.",null],["Once boiling, turn the heat down to medium-low and simmer about 10 minutes, stirring every couple of minutes, until the pasta is tender and the liquid is thick and saucy.",10],["Add [[2 oz]] cream cheese in chunks and stir until it melts into the sauce.",null],["Top with the sliced green onions and serve.",null]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":483,"protein_g":35,"carbs_g":52,"fat_g":15},"video":"https://www.youtube.com/embed/qV0F5FiXUXw","country":"US","effort_steps":5,"ingredients":[{"item":"smoked paprika","qty":2,"unit":"tsp","group":"Cajun Seasoning"},{"item":"oregano","qty":1,"unit":"tsp","group":"Cajun Seasoning"},{"item":"thyme","qty":1,"unit":"tsp","group":"Cajun Seasoning"},{"item":"garlic powder","qty":0.5,"unit":"tsp","group":"Cajun Seasoning"},{"item":"onion powder","qty":0.5,"unit":"tsp","group":"Cajun Seasoning"},{"item":"cayenne pepper","qty":0.25,"unit":"tsp","group":"Cajun Seasoning"},{"item":"black pepper","qty":0.25,"unit":"tsp","group":"Cajun Seasoning"},{"item":"salt","qty":0.25,"unit":"tsp","group":"Cajun Seasoning"},{"item":"olive oil","qty":1,"unit":"tbsp","group":"Chicken Pasta"},{"item":"butter","qty":1,"unit":"tbsp","group":"Chicken Pasta"},{"item":"boneless, skinless chicken breast","qty":1,"unit":"lb","group":"Chicken Pasta"},{"item":"yellow onion","qty":1,"note":"diced","group":"Chicken Pasta"},{"item":"penne pasta","qty":0.5,"unit":"lb","note":"uncooked","group":"Chicken Pasta"},{"item":"fire roasted diced tomatoes","qty":15,"unit":"oz","group":"Chicken Pasta"},{"item":"chicken broth","qty":2,"unit":"cup","group":"Chicken Pasta"},{"item":"cream cheese","qty":2,"unit":"oz","group":"Chicken Pasta"},{"item":"green onions","qty":3,"note":"sliced","group":"Chicken Pasta"}]}'::jsonb),
('www-chilipeppermadness-com-recipes-dirty-rice', 'Dirty Rice (Classic Cajun, One-Pot)', 'Cajun', 'Chili Pepper Madness', 'https://www.chilipeppermadness.com/recipes/dirty-rice/', 45, 6, 2, 2, 2, 10, 43, array['beef', 'rice', 'broth', 'bell peppers', 'onion', 'garlic', 'celery']::text[], '{"title":"Dirty Rice (Classic Cajun, One-Pot)","cuisine":"Cajun","source":"Chili Pepper Madness","url":"https://www.chilipeppermadness.com/recipes/dirty-rice/","minutes":45,"servings":6,"key":["Ground beef","Rice","Chicken broth","Bell pepper","Onion","Garlic","Celery"],"minor":["Cajun seasoning","Bay leaf","Dried thyme","Chicken livers (optional)","Fresh herbs"],"amounts":{"Ground beef":"10 ounces pork or beef","Rice":"1.5 cups white","Chicken broth":"3 cups","Bell pepper":"1 green","Onion":"1 medium","Garlic":"3 cloves","Celery":"1 rib"},"steps":[["On a clean cutting board, chop the bell pepper, onion, celery and [[3 cloves]] garlic. If using chicken livers, finely chop [[1/2 cup]] of them.",null],["Heat [[1 tbsp]] olive oil in a large skillet or pot over medium heat.",null],["Add the pepper, onion and celery and cook about 5 minutes to soften.",5],["Add the garlic and cook 30 seconds to 1 minute, until fragrant.",0.5],["Add [[10 oz]] ground pork or beef and break it apart with a wooden spoon. Cook 5 to 7 minutes, stirring now and then, until browned.",5],["If using chicken livers, add them now and cook 5 minutes, stirring to break them up.",5],["Stir in [[1 1/2 cups]] uncooked rice, [[3 cups]] chicken broth, [[2 tbsp]] Cajun seasoning, [[1]] bay leaf and [[1 tsp]] dried thyme. Season with salt and pepper.",null],["Bring to a boil, then reduce the heat, cover, and simmer 20 to 30 minutes until the rice is cooked through.",20],["Remove the bay leaf.",null],["Garnish with fresh chopped herbs and serve.",null]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":344,"protein_g":13,"carbs_g":42,"fat_g":13},"video":null,"country":"US","effort_steps":5,"ingredients":[{"item":"olive oil","qty":1,"unit":"tbsp"},{"item":"green bell pepper (or jalapeños/serranos for spicier)","qty":1,"note":"chopped"},{"item":"onion","qty":1,"unit":"medium","note":"chopped"},{"item":"celery","qty":1,"unit":"rib","note":"chopped"},{"item":"garlic","qty":3,"unit":"clove","note":"chopped"},{"item":"ground pork or ground beef","qty":10,"unit":"oz"},{"item":"chicken livers","qty":0.5,"unit":"cup","note":"finely chopped, optional"},{"item":"white rice (long grain preferred)","qty":1.5,"unit":"cup","note":"uncooked"},{"item":"chicken broth","qty":3,"unit":"cup"},{"item":"Cajun seasoning blend","qty":2,"unit":"tbsp"},{"item":"bay leaf","qty":1},{"item":"dried thyme","qty":1,"unit":"tsp"},{"item":"salt and pepper","note":"to taste"},{"item":"fresh herbs","note":"chopped, for garnish"}]}'::jsonb),
('www-oliviascuisine-com-how-to-cook-rice', 'Brazilian-Style Rice', 'Brazilian', 'Olivia''s Cuisine', 'https://www.oliviascuisine.com/how-to-cook-rice/', 25, 4, 2, 1, 2, 10, 35, array['rice', 'onion', 'garlic']::text[], '{"title":"Brazilian-Style Rice","cuisine":"Brazilian","source":"Olivia''s Cuisine","url":"https://www.oliviascuisine.com/how-to-cook-rice/","minutes":25,"servings":4,"key":["Rice","Onion","Garlic"],"minor":["Vegetable oil"],"amounts":{"Rice":"1 cup long grain (jasmine), washed","Onion":"1 medium","Garlic":"3 cloves"},"steps":[["On a clean cutting board, finely chop the onion and mince [[3 cloves]] garlic.",null],["Wash [[1 cup]] rice in a bowl of water and drain it.",null],["Put [[2 cups]] water in a tea kettle to boil.",null],["In a large pot, heat [[1/4 cup]] vegetable oil over medium-high heat.",null],["Add the onion and garlic and sauté until translucent. Be careful not to burn them!",null],["Add the raw washed rice to the pot and cook, stirring now and then so it doesn''t burn, until it starts forming clumps.",null],["Pour the boiling water into the pot and add [[1 pinch]] salt. Cover and lower the heat to the lowest setting.",null],["Cook for 20 minutes, or until there''s no more water at the bottom. You''ll see little holes forming on the surface and won''t hear any more water.",20],["Turn the heat off, lift the lid slightly, and let the rice sit untouched for 5 more minutes.",5],["Fluff the rice with a fork and serve.",null]],"technique":2,"prep":1,"precision":2,"nutrition":null,"video":null,"country":"BR","effort_steps":5,"ingredients":[{"item":"vegetable oil","qty":0.25,"unit":"cup"},{"item":"white long grain rice (jasmine)","qty":1,"unit":"cup","note":"washed"},{"item":"water","qty":2,"unit":"cup"},{"item":"onion","qty":1,"unit":"medium","note":"finely chopped"},{"item":"garlic","qty":3,"unit":"clove","note":"minced"},{"item":"salt","qty":1,"unit":"pinch"}]}'::jsonb),
('braziliankitchenabroad-com-brazilian-chicken-stroganoff-recipe', 'Brazilian Chicken Stroganoff', 'Brazilian', 'Brazilian Kitchen Abroad', 'https://braziliankitchenabroad.com/brazilian-chicken-stroganoff-recipe/', 30, 6, 4, 2, 2, 8, 52, array['chicken', 'cream', 'tomatoes', 'onion', 'garlic', 'butter']::text[], '{"title":"Brazilian Chicken Stroganoff","cuisine":"Brazilian","source":"Brazilian Kitchen Abroad","url":"https://braziliankitchenabroad.com/brazilian-chicken-stroganoff-recipe/","minutes":30,"servings":6,"key":["Chicken breast","Heavy cream","Tomato sauce","Onion","Garlic","Butter"],"minor":["Ketchup","Parsley","Potato sticks (to serve)"],"amounts":{"Chicken breast":"2 pounds, cubed","Heavy cream":"1.5 cups","Tomato sauce":"1 (15oz) can","Onion":"1 medium-large","Garlic":"3 cloves (or 1 tbsp sofrito)","Butter":"2 tablespoons"},"steps":[["On a clean cutting board, cut [[2 lb]] chicken breasts into cubes. Dice the onion, and mince the garlic if you''re using garlic instead of sofrito.",null],["Put the cubed chicken in a large dish, season with salt and pepper, and set aside.",null],["Place a large heavy-bottomed pan or Dutch oven over medium to high heat. Add [[2 tbsp]] butter and let it melt.",null],["Add the chicken pieces to the pan and cook until they start to brown.",null],["Add the onion and cook until it turns transparent.",null],["Add [[1 tbsp]] sofrito (or the minced garlic) and cook until fragrant.",null],["Stir in [[1 can (15 oz)]] tomato sauce and [[1 tbsp]] ketchup. Bring it to a simmer and let it simmer for 2 to 3 minutes.",2],["Add [[1 1/2 cups]] heavy cream and simmer uncovered for 5 minutes, then serve!",5]],"technique":4,"prep":2,"precision":2,"nutrition":{"calories":423,"protein_g":34,"carbs_g":4,"fat_g":30},"video":null,"country":"BR","effort_steps":5,"ingredients":[{"item":"unsalted butter","qty":2,"unit":"tbsp"},{"item":"skinless, boneless chicken breasts","qty":2,"unit":"lb","note":"cut into cubes"},{"item":"onion","qty":1,"unit":"medium-large","note":"diced, about a heaping cup"},{"item":"Brazilian Sofrito (or 3 garlic cloves)","qty":1,"unit":"tbsp","note":"garlic minced"},{"item":"tomato sauce","qty":1,"unit":"can (15 oz)"},{"item":"ketchup","qty":1,"unit":"tbsp"},{"item":"heavy cream","qty":1.5,"unit":"cup"},{"item":"salt and pepper","note":"to taste"}]}'::jsonb),
('www-veganricha-com-atakilt-wat-ethiopian-cabbage-potato', 'Atakilt Wat (Ethiopian Cabbage, Potato and Carrots)', 'Ethiopian', 'Vegan Richa', 'https://www.veganricha.com/atakilt-wat-ethiopian-cabbage-potato/', 50, 2, 4, 3, 2, 11, 58, array['cabbage', 'potatoes', 'carrots', 'onion', 'garlic', 'ginger']::text[], '{"title":"Atakilt Wat (Ethiopian Cabbage, Potato and Carrots)","cuisine":"Ethiopian","source":"Vegan Richa","url":"https://www.veganricha.com/atakilt-wat-ethiopian-cabbage-potato/","minutes":50,"servings":2,"key":["Cabbage","Potatoes","Carrots","Onion","Garlic","Ginger"],"minor":["Turmeric","Cumin","Fenugreek","Cardamom","Cinnamon","Cloves","Green chili"],"amounts":{"Cabbage":"1/2 head","Potatoes":"2 medium (1.5 cups)","Carrots":"3/4 cup sliced","Onion":"1/2 cup chopped","Garlic":"2 cloves","Ginger":"1 tsp minced"},"steps":[["On a clean cutting board, mince [[2 cloves]] garlic and [[1 tsp]] ginger, chop the green chili (if using) and chop [[1/2 cup]] onion.",null],["Slice [[3/4 cup]] carrots, chop [[2 medium]] potatoes, and finely chop [[1/2 head]] cabbage. Keep each in its own pile.",null],["In a large skillet, heat [[1 tsp]] oil over medium-low heat.",null],["Once hot, add the garlic, ginger, chili and onion. Mix and cook for 4 minutes.",4],["Add [[1/4 tsp]] cumin, [[1/2 tsp]] turmeric (up to [[3/4 tsp]]), [[1/4 tsp]] fenugreek, [[1/4 tsp]] cardamom, [[1/4 tsp]] cinnamon, [[1/8 tsp]] cloves and a generous dash of black pepper.",null],["Mix and cook for 3 minutes to infuse the oil, until the onion is golden.",3],["Add the carrots and potatoes to the skillet and mix well.",null],["Add the cabbage and [[1/4 tsp]] salt. Mix well, cover, and cook for 15 minutes, stirring once halfway.",15],["Add [[1/4 tsp]] or more salt and the remaining [[1 tsp]] olive oil and mix in. If it looks dry, add a splash of water to loosen anything stuck to the pan.",null],["Cover and cook another 15 minutes, or until the potatoes are tender.",15],["Serve hot with injera (Ethiopian flatbread) and lentil wat.",null]],"technique":4,"prep":3,"precision":2,"nutrition":{"calories":259,"protein_g":9,"carbs_g":48,"fat_g":5},"video":"https://www.youtube.com/embed/KHU9nUHqAdk","country":"ET","effort_steps":4,"ingredients":[{"item":"olive oil or vegan butter","qty":2,"unit":"tsp","note":"divided"},{"item":"garlic","qty":2,"unit":"clove","note":"minced"},{"item":"ginger","qty":1,"unit":"tsp","note":"minced"},{"item":"green chili","qty":1,"note":"chopped, optional"},{"item":"onion","qty":0.5,"unit":"cup","note":"chopped"},{"item":"cumin powder","qty":0.25,"unit":"tsp"},{"item":"turmeric powder","qty":0.5,"qtyMax":0.75,"unit":"tsp"},{"item":"fenugreek seeds or powder","qty":0.25,"unit":"tsp"},{"item":"cardamom powder","qty":0.25,"unit":"tsp"},{"item":"cinnamon powder","qty":0.25,"unit":"tsp"},{"item":"cloves powder","qty":0.125,"unit":"tsp"},{"item":"black pepper","note":"a generous dash"},{"item":"carrots","qty":0.75,"unit":"cup","note":"sliced"},{"item":"potatoes","qty":2,"unit":"medium","note":"chopped (1.5 loaded cups)"},{"item":"cabbage","qty":0.5,"unit":"head","note":"finely chopped"},{"item":"salt","qty":0.5,"unit":"tsp","note":"divided"}]}'::jsonb),
('urbanfarmie-com-kik-alicha', 'Kik Alicha (Ethiopian Split Pea Stew)', 'Ethiopian', 'Urban Farmie', 'https://urbanfarmie.com/kik-alicha/', 60, 4, 4, 2, 1, 12, 57, array['peas', 'onion', 'garlic', 'ginger']::text[], '{"title":"Kik Alicha (Ethiopian Split Pea Stew)","cuisine":"Ethiopian","source":"Urban Farmie","url":"https://urbanfarmie.com/kik-alicha/","minutes":60,"servings":4,"key":["Yellow split peas","Onion","Garlic","Ginger"],"minor":["Turmeric"],"amounts":{"Yellow split peas":"1 cup","Onion":"1 large","Garlic":"2 cloves","Ginger":"1 inch piece"},"steps":[["Rinse [[1 cup]] yellow split peas under cold water. If you have time, soak them for about an hour to cut the cooking time and make them easier to digest.",null],["On a clean cutting board, finely chop the onion and mince [[2 cloves]] garlic and the [[1 inch piece]] of ginger.",null],["In a large pot, add the split peas and [[3 cups]] water. Bring to a boil, then reduce to a simmer.",null],["Cover and cook for about 25 to 35 minutes, taking the lid off for the last 10 minutes.",25],["While the peas cook, heat [[2 tbsp]] olive oil in a skillet over medium heat.",null],["Add the onion to the skillet and sauté until soft and translucent, about 5 to 7 minutes.",5],["Add the garlic and ginger and sauté another 2 minutes, until fragrant.",2],["Stir in [[1 tsp]] turmeric and cook 1 more minute to release its flavor.",1],["Add the onion mixture from the skillet into the pot of cooked split peas. Add [[1 tsp]] salt, adjusting to taste.",null],["Simmer on low heat, uncovered, for another 10 to 15 minutes. If the stew is too thick, add a little water.",10],["Taste and adjust the seasoning if needed, then turn off the heat.",null],["Serve warm with injera (Ethiopian flatbread) or rice.",null]],"technique":4,"prep":2,"precision":1,"nutrition":{"calories":246,"protein_g":13,"carbs_g":33,"fat_g":8},"video":null,"country":"ET","effort_steps":5,"ingredients":[{"item":"yellow split peas","qty":1,"unit":"cup"},{"item":"water","qty":3,"unit":"cup"},{"item":"olive oil","qty":2,"unit":"tbsp"},{"item":"onion","qty":1,"unit":"large","note":"finely chopped"},{"item":"garlic","qty":2,"unit":"clove","note":"minced"},{"item":"ginger","qty":1,"unit":"inch piece","note":"minced"},{"item":"turmeric","qty":1,"unit":"tsp"},{"item":"salt","qty":1,"unit":"tsp","note":"adjust to taste"}]}'::jsonb),
('www-sbs-com-au-food-recipes-enqulal-firfir-ethiopian-scrambled-eggs', 'Enqulal Firfir (Ethiopian Scrambled Eggs)', 'Ethiopian', 'SBS Food', 'https://www.sbs.com.au/food/recipes/enqulal-firfir-ethiopian-scrambled-eggs', 30, 2, 2, 2, 2, 12, 40, array['eggs', 'onion', 'tomatoes', 'tomato paste', 'garlic']::text[], '{"title":"Enqulal Firfir (Ethiopian Scrambled Eggs)","cuisine":"Ethiopian","source":"SBS Food","url":"https://www.sbs.com.au/food/recipes/enqulal-firfir-ethiopian-scrambled-eggs","minutes":30,"servings":2,"key":["Eggs","Onion","Tomatoes","Tomato paste","Garlic"],"minor":["Long green chilli","Coriander","Teff flour (kita flatbread)","Plain flour (kita flatbread)","Nigella seeds"],"amounts":{"Eggs":"4","Onion":"1 red","Tomatoes":"1","Tomato paste":"1 tbsp","Garlic":"2 cloves"},"steps":[["On a clean cutting board, finely chop the red onion, chop the tomato and chop the green chilli. Have the [[2 cloves]] garlic ready.",null],["Crack [[4]] eggs into a new bowl and beat them lightly with a fork.",null],["For the kita: in a new bowl, mix [[150 g]] teff flour, [[75 g]] plain flour, [[1 pinch]] salt, [[1 pinch]] nigella seeds and [[1 tbsp]] vegetable oil.",null],["Add [[125 ml]] water and stir until a dough forms. Keep adding water a little at a time until it''s like cookie dough.",null],["Heat the remaining [[1 tbsp]] oil in a non-stick pan over medium heat. Flatten the dough into the pan and press ridges into it with your fingers.",null],["Cover and cook for 4 minutes.",4],["Flip the kita and cook another 3 minutes until cooked through.",3],["Heat [[1 tbsp]] oil in a large pan over medium heat. Add the onion and cook 3 minutes until it starts to soften.",3],["Add the garlic and tomato and cook 3 more minutes until soft. Stir in [[1 tbsp]] tomato paste.",3],["Pour the beaten eggs into the same pan and stir continuously until cooked.",null],["Take the pan off the heat and stir in the chopped green chilli.",null],["Scatter with coriander and serve with the kita alongside for scooping.",null]],"technique":2,"prep":2,"precision":2,"nutrition":null,"video":null,"country":"ET","effort_steps":5,"ingredients":[{"item":"vegetable oil","qty":1,"unit":"tbsp"},{"item":"red onion","qty":1,"note":"finely chopped"},{"item":"garlic","qty":2,"unit":"clove"},{"item":"tomato","qty":1,"note":"chopped"},{"item":"tomato paste","qty":1,"unit":"tbsp"},{"item":"eggs","qty":4,"note":"lightly beaten"},{"item":"long green chilli","qty":1,"note":"chopped"},{"item":"coriander sprigs","note":"to serve"},{"item":"teff flour","qty":150,"unit":"g","note":"1 cup","group":"Kita"},{"item":"plain white flour","qty":75,"unit":"g","note":"1/2 cup","group":"Kita"},{"item":"salt","qty":1,"unit":"pinch","group":"Kita"},{"item":"tikur azmud (nigella seeds)","qty":1,"unit":"pinch","group":"Kita"},{"item":"vegetable oil","qty":2,"unit":"tbsp","note":"divided","group":"Kita"},{"item":"water","qty":125,"unit":"ml","note":"plus more as needed (from the method)","group":"Kita"}]}'::jsonb)
